        // Helper: read 1-8 bytes from a Java byte[] at given offset
        fn read_bytes(ctx: &dyn NativeContext, args: &[Value], n: usize) -> Vec<u8> {
            let arr = match args.first() {
                Some(Value::Object(Some(a))) => *a,
                _ => return vec![0; n],
            };
            let off = match args.get(1) {
                Some(Value::Int(i)) => *i as usize,
                _ => 0,
            };
            let mut buf = vec![0u8; n];
            for i in 0..n {
                buf[i] = ctx.get_array_element(arr, off + i).as_int().unwrap_or(0) as u8;
            }
            buf
        }
        fn write_bytes(ctx: &mut dyn NativeContext, args: &[Value], bytes: &[u8]) {
            let arr = match args.first() {
                Some(Value::Object(Some(a))) => *a,
                _ => return,
            };
            let off = match args.get(1) {
                Some(Value::Int(i)) => *i as usize,
                _ => 0,
            };
            for (i, &b) in bytes.iter().enumerate() {
                ctx.set_array_element(arr, off + i, Value::Int(b as i8 as i32));
            }
        }
