    // startVirtualThread(Runnable) -> Thread — creates and starts a virtual thread
    registry.register(
        vt_test,
        "startVirtualThread",
        "(Ljava/lang/Runnable;)Ljava/lang/Thread;",
        |ctx, args| {
            let runnable = args.first().copied().unwrap_or(Value::Object(None));
            let thr = alloc_concurrent_synthetic(ctx, "java/lang/Thread", 5);
            let name = ctx.create_string("virtual-thread");
            ctx.set_field(thr, 0, Value::Object(Some(name))); // name
            ctx.set_field(thr, 1, Value::Int(5)); // priority
            ctx.set_field(thr, 3, runnable); // target Runnable
            ctx.set_field(thr, 4, Value::Int(1)); // virtual=true
            ctx.thread_start(thr)?;
            Ok(Some(Value::Object(Some(thr))))
        },
    );
    // threadIsVirtual(Thread) -> boolean — checks virtual flag
    registry.register(
        vt_test,
        "threadIsVirtual",
        "(Ljava/lang/Thread;)Z",
        |ctx, args| {
            let thr = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Int(0))),
            };
            let num_fields = ctx.object_num_fields(thr);
            if num_fields >= 5 {
                match ctx.get_field(thr, 4) {
                    Value::Int(v) => Ok(Some(Value::Int(if v != 0 { 1 } else { 0 }))),
                    _ => Ok(Some(Value::Int(0))),
                }
            } else {
                Ok(Some(Value::Int(0)))
            }
        },
    );
