fn register_unsafe_natives(r: &mut NativeMethodRegistry) {
    let u = "sun/misc/Unsafe";
    r.register(u, "registerNatives", "()V", native_noop);
    r.register(
        u,
        "objectFieldOffset",
        "(Ljava/lang/reflect/Field;)J",
        native_unsafe_object_field_offset,
    );
    r.register(
        u,
        "staticFieldOffset",
        "(Ljava/lang/reflect/Field;)J",
        native_unsafe_object_field_offset,
    );
    r.register(
        u,
        "arrayBaseOffset",
        "(Ljava/lang/Class;)I",
        native_unsafe_array_base_offset,
    );
    r.register(
        u,
        "arrayIndexScale",
        "(Ljava/lang/Class;)I",
        native_unsafe_array_index_scale,
    );
    // CAS
    r.register(
        u,
        "compareAndSwapInt",
        "(Ljava/lang/Object;JII)Z",
        native_unsafe_cas_int,
    );
    r.register(
        u,
        "compareAndSwapLong",
        "(Ljava/lang/Object;JJJ)Z",
        native_unsafe_cas_long,
    );
    r.register(
        u,
        "compareAndSwapObject",
        "(Ljava/lang/Object;JLjava/lang/Object;Ljava/lang/Object;)Z",
        native_unsafe_cas_object,
    );
    // Volatile get/put
    r.register(
        u,
        "getIntVolatile",
        "(Ljava/lang/Object;J)I",
        native_unsafe_get_int_volatile,
    );
    r.register(
        u,
        "putIntVolatile",
        "(Ljava/lang/Object;JI)V",
        native_unsafe_put_int_volatile,
    );
    r.register(
        u,
        "getLongVolatile",
        "(Ljava/lang/Object;J)J",
        native_unsafe_get_long_volatile,
    );
    r.register(
        u,
        "putLongVolatile",
        "(Ljava/lang/Object;JJ)V",
        native_unsafe_put_long_volatile,
    );
    r.register(
        u,
        "getObjectVolatile",
        "(Ljava/lang/Object;J)Ljava/lang/Object;",
        native_unsafe_get_object_volatile,
    );
    r.register(
        u,
        "putObjectVolatile",
        "(Ljava/lang/Object;JLjava/lang/Object;)V",
        native_unsafe_put_object_volatile,
    );
    // Non-volatile get/put
    r.register(
        u,
        "getObject",
        "(Ljava/lang/Object;J)Ljava/lang/Object;",
        native_unsafe_get_object,
    );
    r.register(
        u,
        "putObject",
        "(Ljava/lang/Object;JLjava/lang/Object;)V",
        native_unsafe_put_object,
    );
    r.register(u, "getInt", "(Ljava/lang/Object;J)I", native_unsafe_get_int);
    r.register(
        u,
        "putInt",
        "(Ljava/lang/Object;JI)V",
        native_unsafe_put_int,
    );
    r.register(
        u,
        "getLong",
        "(Ljava/lang/Object;J)J",
        native_unsafe_get_long,
    );
    r.register(
        u,
        "putLong",
        "(Ljava/lang/Object;JJ)V",
        native_unsafe_put_long,
    );
    // Allocation
    r.register(
        u,
        "allocateInstance",
        "(Ljava/lang/Class;)Ljava/lang/Object;",
        native_unsafe_allocate_instance,
    );
    // Fences
    r.register(u, "storeFence", "()V", native_unsafe_fence);
    r.register(u, "loadFence", "()V", native_unsafe_fence);
    r.register(u, "fullFence", "()V", native_unsafe_fence);
    // Park/Unpark
    r.register(u, "park", "(ZJ)V", native_unsafe_park);
    r.register(u, "unpark", "(Ljava/lang/Object;)V", native_unsafe_unpark);
    // Compound ops
    r.register(
        u,
        "getAndAddInt",
        "(Ljava/lang/Object;JI)I",
        native_unsafe_get_and_add_int,
    );
    r.register(
        u,
        "getAndSetInt",
        "(Ljava/lang/Object;JI)I",
        native_unsafe_get_and_set_int,
    );
    // getAndAddLong / getAndSetLong — needed by AtomicLong
    r.register(
        u,
        "getAndAddLong",
        "(Ljava/lang/Object;JJ)J",
        native_unsafe_get_and_add_long,
    );
    r.register(
        u,
        "getAndSetLong",
        "(Ljava/lang/Object;JJ)J",
        native_unsafe_get_and_set_long,
    );
    r.register(
        u,
        "getAndSetObject",
        "(Ljava/lang/Object;JLjava/lang/Object;)Ljava/lang/Object;",
        native_unsafe_get_and_set_object,
    );
    // Primitive field access (boolean, byte, short, float, double, char)
    r.register(u, "getBoolean", "(Ljava/lang/Object;J)Z", native_unsafe_get_int);
    r.register(u, "putBoolean", "(Ljava/lang/Object;JZ)V", native_unsafe_put_int);
    r.register(u, "getByte", "(Ljava/lang/Object;J)B", native_unsafe_get_int);
    r.register(u, "putByte", "(Ljava/lang/Object;JB)V", native_unsafe_put_int);
    r.register(u, "getShort", "(Ljava/lang/Object;J)S", native_unsafe_get_int);
    r.register(u, "putShort", "(Ljava/lang/Object;JS)V", native_unsafe_put_int);
    r.register(u, "getFloat", "(Ljava/lang/Object;J)F", native_unsafe_get_float);
    r.register(u, "putFloat", "(Ljava/lang/Object;JF)V", native_unsafe_put_float);
    r.register(u, "getDouble", "(Ljava/lang/Object;J)D", native_unsafe_get_double);
    r.register(u, "putDouble", "(Ljava/lang/Object;JD)V", native_unsafe_put_double);
    r.register(u, "getChar", "(Ljava/lang/Object;J)C", native_unsafe_get_int);
    r.register(u, "putChar", "(Ljava/lang/Object;JC)V", native_unsafe_put_int);
    // Volatile variants for primitive types
    r.register(u, "getBooleanVolatile", "(Ljava/lang/Object;J)Z", native_unsafe_get_int_volatile);
    r.register(u, "putBooleanVolatile", "(Ljava/lang/Object;JZ)V", native_unsafe_put_int_volatile);
    r.register(u, "getByteVolatile", "(Ljava/lang/Object;J)B", native_unsafe_get_int_volatile);
    r.register(u, "putByteVolatile", "(Ljava/lang/Object;JB)V", native_unsafe_put_int_volatile);
    r.register(u, "getShortVolatile", "(Ljava/lang/Object;J)S", native_unsafe_get_int_volatile);
    r.register(u, "putShortVolatile", "(Ljava/lang/Object;JS)V", native_unsafe_put_int_volatile);
    r.register(u, "getFloatVolatile", "(Ljava/lang/Object;J)F", native_unsafe_get_int_volatile);
    r.register(u, "putFloatVolatile", "(Ljava/lang/Object;JF)V", native_unsafe_put_int_volatile);
    r.register(u, "getDoubleVolatile", "(Ljava/lang/Object;J)D", native_unsafe_get_long_volatile);
    r.register(u, "putDoubleVolatile", "(Ljava/lang/Object;JD)V", native_unsafe_put_long_volatile);
    r.register(u, "getCharVolatile", "(Ljava/lang/Object;J)C", native_unsafe_get_int_volatile);
    r.register(u, "putCharVolatile", "(Ljava/lang/Object;JC)V", native_unsafe_put_int_volatile);
    // copyMemory
    r.register(u, "copyMemory", "(Ljava/lang/Object;JLjava/lang/Object;JJ)V", native_unsafe_copy_memory);
    r.register(u, "setMemory", "(Ljava/lang/Object;JJB)V", native_unsafe_set_memory);
    // pageSize
    r.register(u, "pageSize", "()I", |_ctx, _args| Ok(Some(Value::Int(4096))));
    // addressSize
    r.register(u, "addressSize", "()I", |_ctx, _args| Ok(Some(Value::Int(8))));

    // Also register under jdk/internal/misc/Unsafe (the modern API, same implementations)
    let u2 = "jdk/internal/misc/Unsafe";
    r.register(u2, "registerNatives", "()V", native_noop);
    r.register(u2, "objectFieldOffset", "(Ljava/lang/reflect/Field;)J", native_unsafe_object_field_offset);
    r.register(u2, "staticFieldOffset", "(Ljava/lang/reflect/Field;)J", native_unsafe_object_field_offset);
    r.register(u2, "arrayBaseOffset", "(Ljava/lang/Class;)I", native_unsafe_array_base_offset);
    r.register(u2, "arrayIndexScale", "(Ljava/lang/Class;)I", native_unsafe_array_index_scale);
    r.register(u2, "compareAndSetInt", "(Ljava/lang/Object;JII)Z", native_unsafe_cas_int);
    r.register(u2, "compareAndSetLong", "(Ljava/lang/Object;JJJ)Z", native_unsafe_cas_long);
    r.register(u2, "compareAndSetReference", "(Ljava/lang/Object;JLjava/lang/Object;Ljava/lang/Object;)Z", native_unsafe_cas_object);
    r.register(u2, "getIntVolatile", "(Ljava/lang/Object;J)I", native_unsafe_get_int_volatile);
    r.register(u2, "putIntVolatile", "(Ljava/lang/Object;JI)V", native_unsafe_put_int_volatile);
    r.register(u2, "getLongVolatile", "(Ljava/lang/Object;J)J", native_unsafe_get_long_volatile);
    r.register(u2, "putLongVolatile", "(Ljava/lang/Object;JJ)V", native_unsafe_put_long_volatile);
    r.register(u2, "getReferenceVolatile", "(Ljava/lang/Object;J)Ljava/lang/Object;", native_unsafe_get_object_volatile);
    r.register(u2, "putReferenceVolatile", "(Ljava/lang/Object;JLjava/lang/Object;)V", native_unsafe_put_object_volatile);
    // Acquire/Release variants — same as volatile in our single-threaded model
    r.register(u2, "getReferenceAcquire", "(Ljava/lang/Object;J)Ljava/lang/Object;", native_unsafe_get_object_volatile);
    r.register(u2, "putReferenceRelease", "(Ljava/lang/Object;JLjava/lang/Object;)V", native_unsafe_put_object_volatile);
    r.register(u2, "getIntAcquire", "(Ljava/lang/Object;J)I", native_unsafe_get_int_volatile);
    r.register(u2, "putIntRelease", "(Ljava/lang/Object;JI)V", native_unsafe_put_int_volatile);
    r.register(u2, "getLongAcquire", "(Ljava/lang/Object;J)J", native_unsafe_get_long_volatile);
    r.register(u2, "putLongRelease", "(Ljava/lang/Object;JJ)V", native_unsafe_put_long_volatile);
    // Opaque variants — also same semantics for us
    r.register(u2, "getReferenceOpaque", "(Ljava/lang/Object;J)Ljava/lang/Object;", native_unsafe_get_object_volatile);
    r.register(u2, "putReferenceOpaque", "(Ljava/lang/Object;JLjava/lang/Object;)V", native_unsafe_put_object_volatile);
    r.register(u2, "getIntOpaque", "(Ljava/lang/Object;J)I", native_unsafe_get_int_volatile);
    r.register(u2, "putIntOpaque", "(Ljava/lang/Object;JI)V", native_unsafe_put_int_volatile);
    r.register(u2, "getReference", "(Ljava/lang/Object;J)Ljava/lang/Object;", native_unsafe_get_object);
    r.register(u2, "putReference", "(Ljava/lang/Object;JLjava/lang/Object;)V", native_unsafe_put_object);
    r.register(u2, "getInt", "(Ljava/lang/Object;J)I", native_unsafe_get_int);
    r.register(u2, "putInt", "(Ljava/lang/Object;JI)V", native_unsafe_put_int);
    r.register(u2, "getLong", "(Ljava/lang/Object;J)J", native_unsafe_get_long);
    r.register(u2, "putLong", "(Ljava/lang/Object;JJ)V", native_unsafe_put_long);
    // Unaligned access variants (C16). On x86_64 we are little-endian and natively
    // tolerate unaligned loads/stores, so these delegate to the regular aligned
    // natives, which are null-safe via the static_{int,long}_store fallbacks added
    // in C11. The variants with a trailing boolean (bigEndian flag) are handled by
    // the same functions: the base impls only read args up to offset/value and
    // ignore any trailing arg.
    r.register(u2, "getIntUnaligned", "(Ljava/lang/Object;J)I", native_unsafe_get_int);
    r.register(u2, "getIntUnaligned", "(Ljava/lang/Object;JZ)I", native_unsafe_get_int);
    r.register(u2, "putIntUnaligned", "(Ljava/lang/Object;JI)V", native_unsafe_put_int);
    r.register(u2, "putIntUnaligned", "(Ljava/lang/Object;JIZ)V", native_unsafe_put_int);
    r.register(u2, "getLongUnaligned", "(Ljava/lang/Object;J)J", native_unsafe_get_long);
    r.register(u2, "getLongUnaligned", "(Ljava/lang/Object;JZ)J", native_unsafe_get_long);
    r.register(u2, "putLongUnaligned", "(Ljava/lang/Object;JJ)V", native_unsafe_put_long);
    r.register(u2, "putLongUnaligned", "(Ljava/lang/Object;JJZ)V", native_unsafe_put_long);
    r.register(u2, "getShortUnaligned", "(Ljava/lang/Object;J)S", native_unsafe_get_int);
    r.register(u2, "getShortUnaligned", "(Ljava/lang/Object;JZ)S", native_unsafe_get_int);
    r.register(u2, "putShortUnaligned", "(Ljava/lang/Object;JS)V", native_unsafe_put_int);
    r.register(u2, "putShortUnaligned", "(Ljava/lang/Object;JSZ)V", native_unsafe_put_int);
    r.register(u2, "getCharUnaligned", "(Ljava/lang/Object;J)C", native_unsafe_get_int);
    r.register(u2, "getCharUnaligned", "(Ljava/lang/Object;JZ)C", native_unsafe_get_int);
    r.register(u2, "putCharUnaligned", "(Ljava/lang/Object;JC)V", native_unsafe_put_int);
    r.register(u2, "putCharUnaligned", "(Ljava/lang/Object;JCZ)V", native_unsafe_put_int);
    r.register(u2, "storeFence", "()V", native_unsafe_fence);
    r.register(u2, "loadFence", "()V", native_unsafe_fence);
    r.register(u2, "fullFence", "()V", native_unsafe_fence);
    r.register(u2, "park", "(ZJ)V", native_unsafe_park);
    r.register(u2, "unpark", "(Ljava/lang/Object;)V", native_unsafe_unpark);
    r.register(u2, "allocateInstance", "(Ljava/lang/Class;)Ljava/lang/Object;", native_unsafe_allocate_instance);
    r.register(u2, "getAndAddInt", "(Ljava/lang/Object;JI)I", native_unsafe_get_and_add_int);
    r.register(u2, "getAndSetInt", "(Ljava/lang/Object;JI)I", native_unsafe_get_and_set_int);
    r.register(u2, "getAndAddLong", "(Ljava/lang/Object;JJ)J", native_unsafe_get_and_add_long);
    r.register(u2, "getAndSetLong", "(Ljava/lang/Object;JJ)J", native_unsafe_get_and_set_long);
    r.register(u2, "getAndSetReference", "(Ljava/lang/Object;JLjava/lang/Object;)Ljava/lang/Object;", native_unsafe_get_and_set_object);
    r.register(u2, "copyMemory", "(Ljava/lang/Object;JLjava/lang/Object;JJ)V", native_unsafe_copy_memory);
    r.register(u2, "pageSize", "()I", |_ctx, _args| Ok(Some(Value::Int(4096))));
    r.register(u2, "addressSize", "()I", |_ctx, _args| Ok(Some(Value::Int(8))));

    // --- Remaining Unsafe methods (Phase 44) ---

    // allocateMemory / reallocateMemory / freeMemory — off-heap memory
    // In our managed VM, we simulate these with heap-backed byte arrays.
    r.register(u, "allocateMemory", "(J)J", native_unsafe_allocate_memory);
    r.register(u, "reallocateMemory", "(JJ)J", native_unsafe_allocate_memory_realloc);
    r.register(u, "freeMemory", "(J)V", native_noop_with_this);
    r.register(u2, "allocateMemory0", "(J)J", native_unsafe_allocate_memory);
    r.register(u2, "reallocateMemory0", "(JJ)J", native_unsafe_allocate_memory_realloc);
    r.register(u2, "freeMemory0", "(J)V", native_noop_with_this);

    // monitorEnter / monitorExit — manual synchronization
    r.register(u, "monitorEnter", "(Ljava/lang/Object;)V", native_noop_with_this);
    r.register(u, "monitorExit", "(Ljava/lang/Object;)V", native_noop_with_this);
    r.register(u2, "monitorEnter", "(Ljava/lang/Object;)V", native_noop_with_this);
    r.register(u2, "monitorExit", "(Ljava/lang/Object;)V", native_noop_with_this);

    // throwException — throws a checked exception without declaring it
    r.register(u, "throwException", "(Ljava/lang/Throwable;)V", native_unsafe_throw_exception);
    r.register(u2, "throwException", "(Ljava/lang/Throwable;)V", native_unsafe_throw_exception);

    // shouldBeInitialized — check if class needs initialization
    r.register(u, "shouldBeInitialized", "(Ljava/lang/Class;)Z", |_ctx, _args| Ok(Some(Value::Int(0))));
    r.register(u2, "shouldBeInitialized0", "(Ljava/lang/Class;)Z", |_ctx, _args| Ok(Some(Value::Int(0))));

    // staticFieldBase — returns base object for static field access
    r.register(u, "staticFieldBase", "(Ljava/lang/reflect/Field;)Ljava/lang/Object;", |_ctx, _args| Ok(Some(Value::Object(None))));
    r.register(u2, "staticFieldBase", "(Ljava/lang/reflect/Field;)Ljava/lang/Object;", |_ctx, _args| Ok(Some(Value::Object(None))));

    // ensureClassInitialized — trigger class initialization
    r.register(u, "ensureClassInitialized", "(Ljava/lang/Class;)V", native_noop_with_this);
    r.register(u2, "ensureClassInitialized", "(Ljava/lang/Class;)V", native_noop_with_this);

    // defineClass — define a class from byte array (delegate to ClassLoader)
    r.register(u, "defineClass", "(Ljava/lang/String;[BIILjava/lang/ClassLoader;Ljava/security/ProtectionDomain;)Ljava/lang/Class;", |_ctx, _args| Ok(Some(Value::Object(None))));
    r.register(u2, "defineClass0", "(Ljava/lang/String;[BIILjava/lang/ClassLoader;Ljava/security/ProtectionDomain;)Ljava/lang/Class;", |_ctx, _args| Ok(Some(Value::Object(None))));

    // defineAnonymousClass — legacy API for defining hidden classes (used by old Lambda/invoke)
    // Signature: defineAnonymousClass(Class<?> hostClass, byte[] data, Object[] cpPatches) -> Class<?>
    fn native_unsafe_define_anonymous_class(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
        use std::sync::atomic::Ordering;
        const CAFEBABE: [u8; 4] = [0xCA, 0xFE, 0xBA, 0xBE];

        // args: [unsafe_this, hostClass, byte[], cpPatches]
        let byte_array = match args.get(2) {
            Some(Value::Object(Some(arr))) => *arr,
            _ => return Ok(Some(Value::Object(None))),
        };
        let length = ctx.array_length(byte_array);
        let mut class_bytes = Vec::with_capacity(length);
        for i in 0..length {
            match ctx.get_array_element(byte_array, i) {
                Value::Int(b) => class_bytes.push(b as u8),
                _ => class_bytes.push(0),
            }
        }
        if class_bytes.len() < 4 || class_bytes[0..4] != CAFEBABE {
            return Ok(Some(Value::Object(None)));
        }
        // cpPatches (arg 3) is ignored — legacy constant pool patching not needed.
        let id = crate::classloader::HIDDEN_CLASS_COUNTER.fetch_add(1, Ordering::Relaxed);
        let anon_name = format!("anonymous/0x{:x}", id);
        match ctx.define_class_from_bytes(&anon_name, &class_bytes) {
            Some(cid) => {
                ctx.set_class_hidden(cid);
                let mirror = ctx.get_class_mirror(cid);
                Ok(Some(Value::Object(Some(mirror))))
            }
            None => Ok(Some(Value::Object(None))),
        }
    }
    r.register(u, "defineAnonymousClass", "(Ljava/lang/Class;[B[Ljava/lang/Object;)Ljava/lang/Class;", native_unsafe_define_anonymous_class);
    r.register(u2, "defineAnonymousClass", "(Ljava/lang/Class;[B[Ljava/lang/Object;)Ljava/lang/Class;", native_unsafe_define_anonymous_class);
}

/// Extract the field offset (slot index) from args at the given position.
/// In our VM, offset = slot index (not byte offset).
pub(crate) fn unsafe_offset(args: &[Value], pos: usize) -> usize {
    match args.get(pos) {
        Some(Value::Long(off)) => *off as usize,
        Some(Value::Int(off)) => *off as usize,
        // T19.H1 / T10.9.E — accept a Double/Float with the bit pattern of
        // a 64-bit long. CompactValue on the invoke-argument boundary is
        // the one remaining decode drift site: invoke arg-pop still uses
        // `stack.pop()` which calls `to_value`, surfacing untagged long
        // bits as `Value::Double`. T10.9.E's descriptor-aware field
        // getter in `NativeContextImpl::get_field` eliminates drift when
        // natives read a long via `ctx.get_field` — but the caller-side
        // argument decode lives in `execute_invoke` / `execute_invokestatic`
        // which are outside T10.9.E's ownership, so we keep the
        // bit-reinterpreting arms as a defensive bridge.
        //
        // Removal prerequisites: invoke arg-pop must parse the method
        // descriptor and pop each arg via a descriptor-aware helper
        // instead of the generic `.pop()?`. Once that lands, every
        // `offset: long` parameter arrives as `Value::Long` and these
        // arms become unreachable.
        Some(Value::Double(d)) => d.to_bits() as usize,
        Some(Value::Float(f)) => f.to_bits() as usize,
        _ => 0,
    }
}

/// Convert a byte offset (as used by `Unsafe` on arrays) to an array element
/// index. Real-JDK classes like `ConcurrentHashMap` compute offsets via
/// `(i << ASHIFT) + ABASE` where `ABASE=16` (arrayBaseOffset) and `ASHIFT`
/// is `log2(arrayIndexScale)` for the element type. Our VM's
/// `get_array_element` / `set_array_element` take element indices, not byte
/// offsets, so we need to undo that transform.
///
/// **K1-family fix (CHM resize):** the prior heuristic
/// `if offset < len { return offset; }` mis-interpreted byte offsets that
/// happened to be smaller than the array length. For a 32-bucket
/// `ConcurrentHashMap` table, byte offsets 16, 24 (for indices 0, 1) are
/// less than length 32, so they were returned as-is — addressing slots
/// 16, 24 instead of 0, 1.  Symptom: after CHM's first transfer pass the
/// keys whose new-table indices have byte offsets in `[ABASE, len)` are
/// orphaned (`get` returns null).
///
/// New rule: prefer the byte-offset decode (`(offset - ABASE) / scale`)
/// whenever the offset is a *plausible* byte offset — i.e. `offset >= ABASE`,
/// aligned to `scale`, and the decoded index is in range `0..len`.  Only
/// fall back to the legacy "offset is already an index" path when the
/// offset is below `ABASE` (which is impossible for a real `Unsafe`-style
/// byte offset, but pre-existing synthetic stub call sites in our codebase
/// pass raw indices like 0, 1, 2 directly).
pub(crate) fn unsafe_array_index_from_offset(
    ctx: &dyn NativeContext,
    obj: rustjvm_types::ObjectRef,
    offset: usize,
) -> usize {
    let len = ctx.array_length(obj);
    let scale = match ctx.heap_element_type_of(obj) {
        rustjvm_types::ArrayElementType::Boolean
        | rustjvm_types::ArrayElementType::Byte => 1usize,
        rustjvm_types::ArrayElementType::Char
        | rustjvm_types::ArrayElementType::Short => 2usize,
        rustjvm_types::ArrayElementType::Int
        | rustjvm_types::ArrayElementType::Float => 4usize,
        rustjvm_types::ArrayElementType::Long
        | rustjvm_types::ArrayElementType::Double
        | rustjvm_types::ArrayElementType::Reference => 8usize,
    };
    // ABASE is 16 in `native_unsafe_array_base_offset`; matching JDK layout.
    const ABASE: usize = 16;
    if offset >= ABASE {
        let raw_idx = offset - ABASE;
        if raw_idx % scale == 0 {
            let decoded = raw_idx / scale;
            if decoded < len {
                return decoded;
            }
        }
        // Byte-offset shape but out of bounds — return the decoded index so
        // the caller's bounds check fails cleanly rather than aliasing a
        // valid slot.
        (offset - ABASE) / scale
    } else {
        // offset < ABASE — cannot be a byte offset (real `Unsafe` byte
        // offsets always start at ABASE). Treat as a raw element index for
        // the legacy synthetic-stub callers that pass 0/1/2 directly.
        offset
    }
}

/// Extract the object from args at the given position.
pub(crate) fn unsafe_obj(args: &[Value], pos: usize) -> Option<rustjvm_types::ObjectRef> {
    match args.get(pos) {
        Some(Value::Object(Some(obj))) => Some(*obj),
        _ => None,
    }
}

/// Fallback store for Unsafe.{getAndAdd,CAS,get,put}Long on a null object
/// (static-field access via absolute offset). Used to service callers like
/// `Thread$ThreadIdentifiers.next()` which invoke `Unsafe.getAndAddLong(null,
/// NEXT_TID_OFFSET, 1)` against a static `long` field. Without this, the
/// unwrap on a null receiver would panic and abort the whole VM.
fn static_long_store() -> &'static std::sync::Mutex<std::collections::HashMap<usize, i64>> {
    static T: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<usize, i64>>> =
        std::sync::OnceLock::new();
    T.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

fn static_int_store() -> &'static std::sync::Mutex<std::collections::HashMap<usize, i32>> {
    static T: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<usize, i32>>> =
        std::sync::OnceLock::new();
    T.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

fn static_obj_store() -> &'static std::sync::Mutex<std::collections::HashMap<usize, Option<rustjvm_types::ObjectRef>>> {
    static T: std::sync::OnceLock<std::sync::Mutex<std::collections::HashMap<usize, Option<rustjvm_types::ObjectRef>>>> =
        std::sync::OnceLock::new();
    T.get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
}

fn native_unsafe_object_field_offset(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    // args[0] = Unsafe this, args[1] = Field object.
    // Use read_field_meta so the slot index is read from the RustJVM
    // extra-metadata slot (the JDK `slot` field has different semantics
    // and won't match our heap offsets).
    if let Some(Value::Object(Some(field_obj))) = args.get(1) {
        // C32: Buffer.address probe — Netty's PlatformDependent0.<clinit>
        // reads Buffer.address via Unsafe.getLong(directBuffer, offset) to
        // verify a direct buffer's native address slot is accessible. If it
        // reads zero (or an uninitialised Object slot in our VM), PD0$4.run
        // returns null, and PD0.<clinit> then calls getMessage() on the null
        // "Throwable" → NPE. Use a sentinel offset (i64::MAX - 1) that
        // native_unsafe_get_long recognises and answers with a non-zero
        // long so Netty treats Buffer.address as available.
        if let Some((class_id, field_name)) =
            crate::lang_class::field_class_and_name(ctx, *field_obj)
        {
            let cname = ctx.class_name_of_id(class_id).unwrap_or_default();
            if field_name == "address" && cname == "java/nio/Buffer" {
                return Ok(Some(Value::Long(BUFFER_ADDRESS_SENTINEL as i64)));
            }
        }
        let (_is_static, _cid, slot, _desc) =
            crate::lang_class::read_field_meta(ctx, *field_obj);

        // T19.H1: if `read_field_meta` returned 0 but the Field actually
        // names an instance field of a superclass layout (the typical case
        // for AbstractMap subclasses), look it up by (declaring class,
        // field name) via the inheritance-aware path we added to
        // objectFieldOffset1. This is the fallback that unblocks the
        // ConcurrentHashMap.initTable livelock — the synthetic Field
        // emitted by `getDeclaredField` for sizeCtl had rj_slot=0 because
        // its populator only set the JDK `slot` field (which is an
        // opaque index, not our heap slot), and the fallback chain above
        // only reads two well-known slots. The inheritance walk below
        // guarantees the returned offset is the real heap slot.
        let effective_slot = if slot == 0 {
            if let Some((class_id, field_name)) =
                crate::lang_class::field_class_and_name(ctx, *field_obj)
            {
                let mut cid_opt = Some(class_id);
                let mut resolved: Option<usize> = None;
                while let Some(cid) = cid_opt {
                    let fields = ctx.declared_fields(cid);
                    if let Some(f) = fields.iter().find(|f| !f.is_static && f.name == field_name) {
                        resolved = Some(f.slot_index);
                        break;
                    }
                    cid_opt = ctx.superclass_of(cid);
                }
                if let Some(s) = resolved {
                    if s != 0 {
                        static FIXED: std::sync::OnceLock<
                            std::sync::Mutex<std::collections::HashSet<(String, String)>>,
                        > = std::sync::OnceLock::new();
                        let seen = FIXED
                            .get_or_init(|| std::sync::Mutex::new(std::collections::HashSet::new()));
                        let cname = ctx.class_name_of_id(class_id).unwrap_or_default();
                        let mut g = seen.lock().unwrap_or_else(|e| e.into_inner());
                        if g.insert((cname.clone(), field_name.clone())) {
                            tracing::info!(
                                target: "rustjvm::unsafe",
                                "objectFieldOffset(Field): class={cname:?} field={field_name:?} \
                                 rj_slot=0 → resolved via declared_fields walk to slot={s}"
                            );
                        }
                    }
                    s
                } else {
                    slot
                }
            } else {
                slot
            }
        } else {
            slot
        };

        return Ok(Some(Value::Long(effective_slot as i64)));
    }
    Ok(Some(Value::Long(0)))
}

// Sentinel offset (chosen in the usize-sparse high range to not collide
// with real slot indices) for Buffer.address probes; recognised by
// native_unsafe_get_long which answers non-zero.
pub(crate) const BUFFER_ADDRESS_SENTINEL: usize = 0x7fff_ffff_ffff_fffe;

/// `Unsafe.arrayBaseOffset(Class)` — byte offset of element 0 from the
/// array object's base. Real HotSpot returns 16 on 64-bit (object header
/// size). JCTools `UnsafeRefArrayAccess.<clinit>` and similar consumers
/// use this value as-is for pointer arithmetic, but nothing in our VM
/// actually dereferences the computed address; we only need the static
/// initializers to accept the value. Returning 16 matches the 64-bit
/// HotSpot layout and keeps JCTools happy.
pub(crate) fn native_unsafe_array_base_offset(
    _ctx: &mut dyn NativeContext,
    _args: &[Value],
) -> MethodCallResult {
    Ok(Some(Value::Int(16)))
}

/// `Unsafe.arrayIndexScale(Class)` — element size in bytes. JCTools'
/// `UnsafeRefArrayAccess.<clinit>` computes `pointer size` from the scale
/// of `Object[]` and throws `IllegalStateException: Unknown pointer size`
/// for anything other than 4 or 8. We derive the scale from the array
/// element type encoded in the Class mirror's name (JVMS descriptor form,
/// e.g. `[I`, `[J`, `[Ljava/lang/Object;`). Scale matches HotSpot's
/// 64-bit layout without compressed oops:
///   `[Z` / `[B` → 1
///   `[S` / `[C` → 2
///   `[I` / `[F` → 4
///   `[J` / `[D` / `[L...;` / `[[...` → 8
/// Non-array classes or unknown shapes default to 1 (matches the previous
/// catch-all behaviour for defensive callers).
pub(crate) fn native_unsafe_array_index_scale(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    // args[0] = Unsafe this, args[1] = Class mirror of the array type.
    let scale = match args.get(1) {
        Some(Value::Object(Some(mirror))) => {
            let name = crate::lang_class::mirror_class_name(ctx, *mirror)
                .unwrap_or_default();
            array_index_scale_for_name(&name)
        }
        _ => 1,
    };
    Ok(Some(Value::Int(scale)))
}

/// Derive the `Unsafe.arrayIndexScale` value from an array class's
/// internal name (e.g. `[I`, `[Ljava/lang/Object;`). Returns 1 for
/// non-array or unrecognised shapes.
pub(crate) fn array_index_scale_for_name(name: &str) -> i32 {
    let bytes = name.as_bytes();
    if bytes.first() != Some(&b'[') {
        return 1;
    }
    match bytes.get(1).copied() {
        Some(b'Z') | Some(b'B') => 1,                 // boolean, byte
        Some(b'S') | Some(b'C') => 2,                 // short, char
        Some(b'I') | Some(b'F') => 4,                 // int, float
        Some(b'J') | Some(b'D') => 8,                 // long, double
        Some(b'L') | Some(b'[') => 8,                 // reference / nested array
        _ => 1,
    }
}

pub(crate) fn native_unsafe_cas_int(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args: [unsafe, obj, offset(long), expected(int), new(int)]
    let offset = unsafe_offset(args, 2);
    let expected = args.get(3).copied().unwrap_or(Value::Int(0));
    let new_val = args.get(4).copied().unwrap_or(Value::Int(0));
    let obj = match unsafe_obj(args, 1) {
        Some(o) => o,
        None => {
            let mut map = static_int_store().lock().unwrap_or_else(|e| e.into_inner());
            let cur = *map.entry(offset).or_insert(0);
            let ex = if let Value::Int(e) = expected { e } else { 0 };
            let nv = if let Value::Int(n) = new_val { n } else { 0 };
            let ok = cur == ex;
            if ok { map.insert(offset, nv); }
            return Ok(Some(Value::Int(if ok { 1 } else { 0 })));
        }
    };
    if ctx.heap_kind_of(obj) == rustjvm_types::ObjectKind::Array {
        // Route through the locked CAS path so concurrent threads can't
        // interleave inside the load+compare+store. See the matching note
        // in `native_unsafe_cas_object` above.
        let idx = unsafe_array_index_from_offset(ctx, obj, offset);
        let result = ctx.compare_and_swap_field(obj, idx, expected, new_val);
        return Ok(Some(Value::Int(if result { 1 } else { 0 })));
    }
    let result = ctx.compare_and_swap_field(obj, offset, expected, new_val);
    Ok(Some(Value::Int(if result { 1 } else { 0 })))
}

fn native_unsafe_cas_long(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args: [unsafe, obj, offset(long), expected(long), new(long)]
    let offset = unsafe_offset(args, 2);
    let expected = args.get(3).copied().unwrap_or(Value::Long(0));
    let new_val = args.get(4).copied().unwrap_or(Value::Long(0));
    let obj = match unsafe_obj(args, 1) {
        Some(o) => o,
        None => {
            let mut map = static_long_store().lock().unwrap_or_else(|e| e.into_inner());
            let cur = *map.entry(offset).or_insert(0);
            let ex = if let Value::Long(e) = expected { e } else { 0 };
            let nv = if let Value::Long(n) = new_val { n } else { 0 };
            let ok = cur == ex;
            if ok { map.insert(offset, nv); }
            return Ok(Some(Value::Int(if ok { 1 } else { 0 })));
        }
    };
    if ctx.heap_kind_of(obj) == rustjvm_types::ObjectKind::Array {
        // Route through the locked CAS path. See `native_unsafe_cas_object`.
        let idx = unsafe_array_index_from_offset(ctx, obj, offset);
        let result = ctx.compare_and_swap_field(obj, idx, expected, new_val);
        return Ok(Some(Value::Int(if result { 1 } else { 0 })));
    }
    let result = ctx.compare_and_swap_field(obj, offset, expected, new_val);
    // T19_H6_CAS_DIAG: temporary probe — log the first few CAS-fails on long
    // instance fields so we can see whether the heap returned a Double-tagged
    // bit pattern (or Object(None)) for a long slot. Rate-limited to 5 entries
    // to avoid flooding when a livelock fires the CAS millions of times.
    if !result {
        use std::sync::atomic::{AtomicU64, Ordering};
        static CAS_DIAG_COUNT: AtomicU64 = AtomicU64::new(0);
        let n = CAS_DIAG_COUNT.fetch_add(1, Ordering::Relaxed);
        if n < 5 {
            let cid = ctx.class_id_of_object(obj);
            let cls = ctx.class_name_of_id(cid).unwrap_or_else(|| "<?>".to_string());
            let current = ctx.get_field_volatile(obj, offset);
            tracing::warn!(
                target: "cas_diag",
                "T19_H6_CAS_DIAG cas_long FAIL #{} class={} slot={} current={:?} expected={:?} new={:?}",
                n, cls, offset, current, expected, new_val
            );
        }
    }
    Ok(Some(Value::Int(if result { 1 } else { 0 })))
}

/// WP4.1 closer — recover an Object reference from a tag-lost `Value::Double`.
///
/// Under heavy AQS contention the invoke-argument pop boundary surfaces an
/// untagged 64-bit raw-pointer stack slot as `Value::Double(...)` because
/// `CompactValue::to_value()` decodes any non-NaN-tagged u64 as `Double`.
/// Native methods whose Java signature declares a reference parameter must
/// recognize this and reconstruct the original `ObjectRef`; otherwise the
/// CAS or store is performed against a denormal-shaped double, corrupting
/// the field's value tag and crashing later reads with "expected object
/// reference, got double(...)".
///
/// Heuristic guard: pointers in our heap arenas are 8-byte aligned and fit
/// in 48 bits (canonical x86-64 user-space).  A `Value::Double` that fails
/// either constraint cannot be a live ObjectRef and is mapped to null —
/// matching the verifier's "primitive in reference slot" recovery for
/// `Int(0)`/`Long(0)`.
fn recover_object_arg(value: Value) -> Value {
    match value {
        Value::Object(_) => value,
        Value::Double(d) => {
            let bits = d.to_bits();
            if bits == 0 {
                Value::Object(None)
            } else if (bits & 0x7) == 0 && bits < (1u64 << 48) {
                // SAFETY: same untagged pointer pattern as written by the
                // sibling thread; ObjectRef::from_raw is a typed wrapper
                // and does not dereference the address until a later heap
                // access validates it.
                Value::Object(Some(unsafe {
                    rustjvm_types::ObjectRef::from_raw(bits as usize as *mut u8)
                }))
            } else {
                Value::Object(None)
            }
        }
        Value::Int(0) | Value::Long(0) => Value::Object(None),
        _ => value,
    }
}

fn native_unsafe_cas_object(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args: [unsafe, obj, offset(long), expected(Object), new(Object)]
    let offset = unsafe_offset(args, 2);
    // WP4.1 closer — recover Object from a tag-lost Double pattern at the
    // invoke-arg boundary; see `recover_object_arg` for rationale.
    let expected = recover_object_arg(args.get(3).copied().unwrap_or(Value::Object(None)));
    let new_val = recover_object_arg(args.get(4).copied().unwrap_or(Value::Object(None)));
    let obj = match unsafe_obj(args, 1) {
        Some(o) => o,
        None => {
            let mut map = static_obj_store().lock().unwrap_or_else(|e| e.into_inner());
            let cur = *map.entry(offset).or_insert(None);
            let ex = if let Value::Object(e) = expected { e } else { None };
            let nv = if let Value::Object(n) = new_val { n } else { None };
            let ok = cur == ex;
            if ok { map.insert(offset, nv); }
            return Ok(Some(Value::Int(if ok { 1 } else { 0 })));
        }
    };
    // ConcurrentHashMap.casTabAt passes byte offsets into an Object[] array,
    // not field slot indices. The shared-VM `compare_and_swap_field` path
    // dispatches on `kind_of(obj) == Array` internally AND grabs the per-
    // object CAS lock — the prior lock-free load+compare+store here did
    // NOT. Observable on `ChmStress` where 64 worker threads racing through
    // `casTabAt` would interleave inside this native and duplicate / drop
    // bin-list head installs. Pre-converting the byte offset to an element
    // index keeps the contract: `compare_and_swap_field` reuses the second
    // arg directly when `is_array` is true.
    if ctx.heap_kind_of(obj) == rustjvm_types::ObjectKind::Array {
        let idx = unsafe_array_index_from_offset(ctx, obj, offset);
        let result = ctx.compare_and_swap_field(obj, idx, expected, new_val);
        return Ok(Some(Value::Int(if result { 1 } else { 0 })));
    }
    let result = ctx.compare_and_swap_field(obj, offset, expected, new_val);
    Ok(Some(Value::Int(if result { 1 } else { 0 })))
}

