/// Helper: create a ConcurrentSkipListMap containing entries in [from, to) range
fn cslm_subrange(
    ctx: &mut dyn NativeContext,
    source: ObjectRef,
    from: Option<Value>,
    to: Option<Value>,
) -> MethodCallResult {
    let size = match ctx.get_field(source, 2) { Value::Int(n) => n as usize, _ => 0 };
    let keys_arr = match ctx.get_field(source, 0) {
        Value::Object(Some(a)) => a,
        _ => return Ok(Some(Value::Object(None))),
    };
    let vals_arr = match ctx.get_field(source, 1) {
        Value::Object(Some(a)) => a,
        _ => return Ok(Some(Value::Object(None))),
    };

    // Build a new map with the subrange
    let result = alloc_concurrent_synthetic(ctx, "java/util/concurrent/ConcurrentSkipListMap", 3);
    let cap = size.max(4);
    let new_keys = ctx.new_array(rustjvm_types::ArrayElementType::Reference, cap);
    let new_vals = ctx.new_array(rustjvm_types::ArrayElementType::Reference, cap);
    ctx.set_field(result, 0, Value::Object(Some(new_keys)));
    ctx.set_field(result, 1, Value::Object(Some(new_vals)));

    let mut count = 0usize;
    for i in 0..size {
        let k = ctx.get_array_element(keys_arr, i);
        if let Value::Object(Some(ek)) = k {
            // Check lower bound
            if let Some(from_key) = from {
                if let Ok(Some(Value::Int(cmp))) = ctx.invoke_virtual(ek, "compareTo", "(Ljava/lang/Object;)I", &[from_key]) {
                    if cmp < 0 { continue; }
                }
            }
            // Check upper bound
            if let Some(to_key) = to {
                if let Ok(Some(Value::Int(cmp))) = ctx.invoke_virtual(ek, "compareTo", "(Ljava/lang/Object;)I", &[to_key]) {
                    if cmp >= 0 { break; }
                }
            }
        }
        ctx.set_array_element(new_keys, count, k);
        ctx.set_array_element(new_vals, count, ctx.get_array_element(vals_arr, i));
        count += 1;
    }
    ctx.set_field(result, 2, Value::Int(count as i32));
    Ok(Some(Value::Object(Some(result))))
}

// --- ReentrantLock ---

fn native_rl_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    ctx.set_field(this, RL_FIELD_OWNER, Value::Long(0)); // no owner
    ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(0));
    ctx.set_field(this, RL_FIELD_FAIR, Value::Int(0));
    Ok(None)
}

fn native_rl_init_fair(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let fair = match args.get(1) {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    ctx.set_field(this, RL_FIELD_OWNER, Value::Long(0));
    ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(0));
    ctx.set_field(this, RL_FIELD_FAIR, Value::Int(fair));
    Ok(None)
}

fn native_rl_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let tid = ctx.thread_id() as i64;
    loop {
        let owner = match ctx.get_field_volatile(this, RL_FIELD_OWNER) {
            Value::Long(v) => v,
            _ => 0,
        };
        if owner == tid {
            // Reentrant: increment hold count (only this thread can touch it)
            let hold = match ctx.get_field(this, RL_FIELD_HOLD_COUNT) {
                Value::Int(v) => v,
                _ => 0,
            };
            ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(hold + 1));
            return Ok(None);
        }
        if owner == 0 {
            // Atomically claim the lock.
            if ctx.compare_and_swap_field(
                this,
                RL_FIELD_OWNER,
                Value::Long(0),
                Value::Long(tid),
            ) {
                ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(1));
                return Ok(None);
            }
            // Lost the race; spin once and retry.
            continue;
        }
        // Owned by another thread — park on the object monitor until released.
        ctx.monitor_enter(this);
        let still_owned = match ctx.get_field_volatile(this, RL_FIELD_OWNER) {
            Value::Long(v) => v != 0 && v != tid,
            _ => false,
        };
        if still_owned {
            ctx.monitor_wait(this, Some(5))?; // short timeout to re-check
        }
        ctx.monitor_exit(this);
    }
}

fn native_rl_unlock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let tid = ctx.thread_id() as i64;
    let owner = match ctx.get_field(this, RL_FIELD_OWNER) {
        Value::Long(v) => v,
        _ => 0,
    };

    if owner != tid {
        return Err(RuntimeError::IllegalMonitorStateException {
            message: "current thread is not owner".to_string(),
        }
        .into());
    }
    let hold = match ctx.get_field(this, RL_FIELD_HOLD_COUNT) {
        Value::Int(v) => v,
        _ => 0,
    };
    if hold <= 1 {
        ctx.set_field(this, RL_FIELD_OWNER, Value::Long(0));
        ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(0));
        // Notify one waiting thread that the lock is available
        ctx.monitor_enter(this);
        ctx.monitor_notify(this)?;
        ctx.monitor_exit(this);
    } else {
        ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(hold - 1));
    }
    Ok(None)
}

fn native_rl_try_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let tid = ctx.thread_id() as i64;
    let owner = match ctx.get_field_volatile(this, RL_FIELD_OWNER) {
        Value::Long(v) => v,
        _ => 0,
    };
    if owner == tid {
        // Reentrant
        let hold = match ctx.get_field(this, RL_FIELD_HOLD_COUNT) {
            Value::Int(v) => v,
            _ => 0,
        };
        ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(hold + 1));
        return Ok(Some(Value::Int(1)));
    }
    // Atomic claim via CAS.
    if ctx.compare_and_swap_field(this, RL_FIELD_OWNER, Value::Long(0), Value::Long(tid)) {
        ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(1));
        Ok(Some(Value::Int(1)))
    } else {
        Ok(Some(Value::Int(0)))
    }
}

fn native_rl_try_lock_timeout(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args: [this, long timeout, TimeUnit unit]
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let tid = ctx.thread_id() as i64;
    let timeout_val = match args.get(1) {
        Some(Value::Long(v)) => *v,
        _ => 0,
    };
    let unit_ord = match args.get(2) {
        Some(Value::Object(Some(u))) => ctx.get_field(*u, 0).as_int().unwrap_or(2),
        _ => 2,
    };
    let timeout_ms = convert_time_unit_to_millis(timeout_val, unit_ord);
    if timeout_ms <= 0 {
        return native_rl_try_lock(ctx, args);
    }
    let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms as u64);
    loop {
        let owner = match ctx.get_field_volatile(this, RL_FIELD_OWNER) {
            Value::Long(v) => v,
            _ => 0,
        };
        if owner == tid {
            let hold = match ctx.get_field(this, RL_FIELD_HOLD_COUNT) {
                Value::Int(v) => v,
                _ => 0,
            };
            ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(hold + 1));
            return Ok(Some(Value::Int(1)));
        }
        if owner == 0 && ctx.compare_and_swap_field(this, RL_FIELD_OWNER, Value::Long(0), Value::Long(tid)) {
            ctx.set_field(this, RL_FIELD_HOLD_COUNT, Value::Int(1));
            return Ok(Some(Value::Int(1)));
        }
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        if remaining.is_zero() {
            return Ok(Some(Value::Int(0)));
        }
        let wait_ms = remaining.as_millis().min(5).max(1) as u64;
        ctx.monitor_enter(this);
        ctx.monitor_wait(this, Some(wait_ms))?;
        ctx.monitor_exit(this);
        if ctx.is_interrupted(true) {
            return Err(rustjvm_types::error::MethodCallFailed::InternalError(
                rustjvm_types::error::VmError::Runtime(rustjvm_types::error::RuntimeError::InterruptedException),
            ));
        }
    }
}

