// ===========================================================================
// Base64 — Encoder/Decoder for basic, URL-safe, and MIME variants
// Encoder = 1-field synthetic (field 0 = Int variant tag)
// Decoder = 1-field synthetic (field 0 = Int variant tag)
// Tags: 0 = basic, 1 = url-safe, 2 = MIME
// ===========================================================================

const B64_FIELD_VARIANT: usize = 0;
const B64_VARIANT_BASIC: i32 = 0;
const B64_VARIANT_URL: i32 = 1;
const B64_VARIANT_MIME: i32 = 2;

const B64_CHARS: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const B64_URL_CHARS: &[u8; 64] =
    b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";

fn b64_encode(input: &[u8], variant: i32, no_padding: bool) -> Vec<u8> {
    let table = if variant == B64_VARIANT_URL {
        B64_URL_CHARS
    } else {
        B64_CHARS
    };
    let mut out = Vec::with_capacity(input.len().div_ceil(3) * 4);
    let mut i = 0;
    let mut line_len = 0;
    while i + 2 < input.len() {
        let b0 = input[i] as u32;
        let b1 = input[i + 1] as u32;
        let b2 = input[i + 2] as u32;
        let triple = (b0 << 16) | (b1 << 8) | b2;
        out.push(table[((triple >> 18) & 0x3F) as usize]);
        out.push(table[((triple >> 12) & 0x3F) as usize]);
        out.push(table[((triple >> 6) & 0x3F) as usize]);
        out.push(table[(triple & 0x3F) as usize]);
        i += 3;
        line_len += 4;
        if variant == B64_VARIANT_MIME && line_len >= 76 {
            out.push(b'\r');
            out.push(b'\n');
            line_len = 0;
        }
    }
    let remaining = input.len() - i;
    if remaining == 1 {
        let b0 = input[i] as u32;
        out.push(table[((b0 >> 2) & 0x3F) as usize]);
        out.push(table[((b0 << 4) & 0x3F) as usize]);
        if !no_padding {
            out.push(b'=');
            out.push(b'=');
        }
    } else if remaining == 2 {
        let b0 = input[i] as u32;
        let b1 = input[i + 1] as u32;
        out.push(table[((b0 >> 2) & 0x3F) as usize]);
        out.push(table[(((b0 << 4) | (b1 >> 4)) & 0x3F) as usize]);
        out.push(table[((b1 << 2) & 0x3F) as usize]);
        if !no_padding {
            out.push(b'=');
        }
    }
    out
}

fn b64_decode_char(c: u8, variant: i32) -> Option<u32> {
    match c {
        b'A'..=b'Z' => Some((c - b'A') as u32),
        b'a'..=b'z' => Some((c - b'a' + 26) as u32),
        b'0'..=b'9' => Some((c - b'0' + 52) as u32),
        b'+' if variant != B64_VARIANT_URL => Some(62),
        b'/' if variant != B64_VARIANT_URL => Some(63),
        b'-' if variant == B64_VARIANT_URL => Some(62),
        b'_' if variant == B64_VARIANT_URL => Some(63),
        _ => None,
    }
}

fn b64_decode(input: &[u8], variant: i32) -> Result<Vec<u8>, String> {
    // Filter out whitespace and line breaks
    let filtered: Vec<u8> = input
        .iter()
        .copied()
        .filter(|&c| c != b'\r' && c != b'\n' && c != b' ' && c != b'\t')
        .collect();

    let mut out = Vec::with_capacity(filtered.len() * 3 / 4);
    let mut i = 0;
    let len = filtered.len();

    while i < len {
        // Skip padding at the end
        if filtered[i] == b'=' {
            break;
        }
        let c0 = b64_decode_char(filtered[i], variant)
            .ok_or_else(|| format!("Invalid base64 char: {}", filtered[i] as char))?;
        if i + 1 >= len {
            return Err("Incomplete base64 input".to_string());
        }
        let c1 = b64_decode_char(filtered[i + 1], variant)
            .ok_or_else(|| format!("Invalid base64 char: {}", filtered[i + 1] as char))?;

        let c2 = if i + 2 < len && filtered[i + 2] != b'=' {
            b64_decode_char(filtered[i + 2], variant)
                .ok_or_else(|| format!("Invalid base64 char: {}", filtered[i + 2] as char))?
        } else {
            out.push(((c0 << 2) | (c1 >> 4)) as u8);
            break;
        };

        let c3 = if i + 3 < len && filtered[i + 3] != b'=' {
            b64_decode_char(filtered[i + 3], variant)
                .ok_or_else(|| format!("Invalid base64 char: {}", filtered[i + 3] as char))?
        } else {
            out.push(((c0 << 2) | (c1 >> 4)) as u8);
            out.push((((c1 & 0xF) << 4) | (c2 >> 2)) as u8);
            break;
        };

        out.push(((c0 << 2) | (c1 >> 4)) as u8);
        out.push((((c1 & 0xF) << 4) | (c2 >> 2)) as u8);
        out.push((((c2 & 0x3) << 6) | c3) as u8);
        i += 4;
    }
    Ok(out)
}

fn register_base64_natives(registry: &mut NativeMethodRegistry) {
    let b64 = "java/util/Base64";
    let enc = "java/util/Base64$Encoder";
    let dec = "java/util/Base64$Decoder";

    // --- Base64 static factory methods ---
    registry.register(
        b64,
        "getEncoder",
        "()Ljava/util/Base64$Encoder;",
        native_b64_get_encoder,
    );
    registry.register(
        b64,
        "getUrlEncoder",
        "()Ljava/util/Base64$Encoder;",
        native_b64_get_url_encoder,
    );
    registry.register(
        b64,
        "getMimeEncoder",
        "()Ljava/util/Base64$Encoder;",
        native_b64_get_mime_encoder,
    );
    registry.register(
        b64,
        "getDecoder",
        "()Ljava/util/Base64$Decoder;",
        native_b64_get_decoder,
    );
    registry.register(
        b64,
        "getUrlDecoder",
        "()Ljava/util/Base64$Decoder;",
        native_b64_get_url_decoder,
    );
    registry.register(
        b64,
        "getMimeDecoder",
        "()Ljava/util/Base64$Decoder;",
        native_b64_get_mime_decoder,
    );

    // --- Encoder methods ---
    registry.register(enc, "encode", "([B)[B", native_b64_encode);
    registry.register(
        enc,
        "encodeToString",
        "([B)Ljava/lang/String;",
        native_b64_encode_to_string,
    );
    registry.register(
        enc,
        "withoutPadding",
        "()Ljava/util/Base64$Encoder;",
        native_b64_without_padding,
    );

    // --- Decoder methods ---
    registry.register(dec, "decode", "([B)[B", native_b64_decode_bytes);
    registry.register(
        dec,
        "decode",
        "(Ljava/lang/String;)[B",
        native_b64_decode_string,
    );
}

fn b64_alloc_encoder(ctx: &mut dyn NativeContext, variant: i32) -> MethodCallResult {
    let encoder = alloc_concurrent_synthetic(ctx, "java/util/Base64$Encoder", 1);
    ctx.set_field(encoder, B64_FIELD_VARIANT, Value::Int(variant));
    Ok(Some(Value::Object(Some(encoder))))
}

fn b64_alloc_decoder(ctx: &mut dyn NativeContext, variant: i32) -> MethodCallResult {
    let decoder = alloc_concurrent_synthetic(ctx, "java/util/Base64$Decoder", 1);
    ctx.set_field(decoder, B64_FIELD_VARIANT, Value::Int(variant));
    Ok(Some(Value::Object(Some(decoder))))
}

fn native_b64_get_encoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_encoder(ctx, B64_VARIANT_BASIC)
}
fn native_b64_get_url_encoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_encoder(ctx, B64_VARIANT_URL)
}
fn native_b64_get_mime_encoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_encoder(ctx, B64_VARIANT_MIME)
}
fn native_b64_get_decoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_decoder(ctx, B64_VARIANT_BASIC)
}
fn native_b64_get_url_decoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_decoder(ctx, B64_VARIANT_URL)
}
fn native_b64_get_mime_decoder(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    b64_alloc_decoder(ctx, B64_VARIANT_MIME)
}

/// Helper: read byte[] arg into a Vec<u8>
fn b64_read_byte_array(ctx: &dyn NativeContext, arr: ObjectRef) -> Vec<u8> {
    let len = ctx.array_length(arr);
    let mut bytes = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(arr, i) {
            bytes.push(b as u8);
        }
    }
    bytes
}

/// Helper: write Vec<u8> into a new byte[] on the heap
fn b64_write_byte_array(ctx: &mut dyn NativeContext, data: &[u8]) -> ObjectRef {
    use rustjvm_types::ArrayElementType;
    let result = ctx.new_array(ArrayElementType::Byte, data.len());
    for (i, &b) in data.iter().enumerate() {
        ctx.set_array_element(result, i, Value::Int(b as i32));
    }
    result
}

/// Helper: get variant tag from encoder/decoder `this`
fn b64_variant(ctx: &dyn NativeContext, this: ObjectRef) -> i32 {
    match ctx.get_field(this, B64_FIELD_VARIANT) {
        Value::Int(v) => v,
        _ => B64_VARIANT_BASIC,
    }
}

fn native_b64_encode(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let src = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let variant = b64_variant(ctx, this);
    let bytes = b64_read_byte_array(ctx, src);
    let encoded = b64_encode(&bytes, variant, false);
    let result = b64_write_byte_array(ctx, &encoded);
    Ok(Some(Value::Object(Some(result))))
}

fn native_b64_encode_to_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let src = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let variant = b64_variant(ctx, this);
    let bytes = b64_read_byte_array(ctx, src);
    let encoded = b64_encode(&bytes, variant, false);
    let s = String::from_utf8_lossy(&encoded);
    let result = ctx.create_string(&s);
    Ok(Some(Value::Object(Some(result))))
}

fn native_b64_without_padding(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let variant = b64_variant(ctx, this);
    b64_alloc_encoder(ctx, variant)
}

fn native_b64_decode_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let src = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let variant = b64_variant(ctx, this);
    let bytes = b64_read_byte_array(ctx, src);
    match b64_decode(&bytes, variant) {
        Ok(decoded) => {
            let result = b64_write_byte_array(ctx, &decoded);
            Ok(Some(Value::Object(Some(result))))
        }
        Err(msg) => Err(RuntimeError::IllegalArgumentException { message: msg }.into()),
    }
}

fn native_b64_decode_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let variant = b64_variant(ctx, this);
    let src_str = match args.get(1) {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => String::new(),
    };
    match b64_decode(src_str.as_bytes(), variant) {
        Ok(decoded) => {
            let result = b64_write_byte_array(ctx, &decoded);
            Ok(Some(Value::Object(Some(result))))
        }
        Err(msg) => Err(RuntimeError::IllegalArgumentException { message: msg }.into()),
    }
}

