// InetAddress = 2-field synthetic (field 0 = hostname, field 1 = address)

/// Resolve the host's actual hostname. Tries, in order:
///   1. `HOSTNAME` env var (Linux/macOS shells set this).
///   2. `COMPUTERNAME` env var (Windows).
///   3. The `hostname` command (portable across all three target OSes,
///      part of the base install on every supported platform).
/// Returns `"localhost"` only if every method fails.
///
/// This is reused by `getLocalHost` and `NetworkInterface.getNetworkInterfaces`
/// so both surface the same name to Java code.
pub(crate) fn resolve_real_hostname() -> String {
    if let Ok(name) = std::env::var("HOSTNAME") {
        let trimmed = name.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    if let Ok(name) = std::env::var("COMPUTERNAME") {
        let trimmed = name.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    // Last-resort portable path: invoke `hostname`. Output may include
    // a trailing newline that we strip, and on Windows it may include
    // the FQDN — we keep the short form to match what HotSpot returns.
    if let Ok(output) = std::process::Command::new("hostname").output() {
        if output.status.success() {
            let raw = String::from_utf8_lossy(&output.stdout);
            let trimmed = raw.trim();
            if !trimmed.is_empty() {
                // Strip an FQDN suffix to match HotSpot which returns the
                // short host name from `getLocalHost().getHostName()`.
                let short = trimmed.split('.').next().unwrap_or(trimmed);
                return short.to_string();
            }
        }
    }
    "localhost".to_string()
}

/// Resolve a hostname to its primary IPv4 address. Used by
/// `InetAddress.getLocalHost` and `NetworkInterface` enumeration.
/// Falls back to `127.0.0.1` if every resolution path fails.
pub(crate) fn resolve_primary_ipv4(hostname: &str) -> String {
    // Direct DNS resolution first.
    if let Ok(addrs) = std::net::ToSocketAddrs::to_socket_addrs(&format!("{hostname}:0")) {
        if let Some(v4) = addrs.into_iter().find(|a| a.is_ipv4()) {
            return v4.ip().to_string();
        }
    }
    // Fallback: connect a UDP socket to a public DNS resolver and read the
    // OS-selected source IP. No packets are sent — `connect` on a `UdpSocket`
    // only sets the default destination. We do not require the public DNS
    // resolver to be reachable; the bind+connect succeeds locally.
    if let Ok(sock) = std::net::UdpSocket::bind("0.0.0.0:0") {
        if sock.connect("8.8.8.8:53").is_ok() {
            if let Ok(addr) = sock.local_addr() {
                if !addr.ip().is_unspecified() {
                    return addr.ip().to_string();
                }
            }
        }
    }
    "127.0.0.1".to_string()
}

fn native_inet_localhost(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    let hostname = resolve_real_hostname();
    let ip = resolve_primary_ipv4(&hostname);
    let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
    let host_ref = ctx.create_string(&hostname);
    let addr_ref = ctx.create_string(&ip);
    ctx.set_field(ia, 0, Value::Object(Some(host_ref)));
    ctx.set_field(ia, 1, Value::Object(Some(addr_ref)));
    Ok(Some(Value::Object(Some(ia))))
}
fn native_inet_get_host_name(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, 0)))
}
fn native_inet_get_host_address(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, 1)))
}
fn native_inet_to_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let host = match ctx.get_field(this, 0) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let addr = match ctx.get_field(this, 1) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let s = format!("{}/{}", host, addr);
    let result = ctx.create_string(&s);
    Ok(Some(Value::Object(Some(result))))
}

/// InetAddress.getByName(String) — resolve hostname to IP address.
/// Uses std::net::ToSocketAddrs for real DNS resolution.
fn native_inet_get_by_name(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let hostname = match args.first() {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => return Ok(Some(Value::Object(None))),
    };

    // Handle null/localhost/loopback
    if hostname.is_empty() || hostname == "localhost" {
        let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
        let host = ctx.create_string("localhost");
        let addr = ctx.create_string("127.0.0.1");
        ctx.set_field(ia, 0, Value::Object(Some(host)));
        ctx.set_field(ia, 1, Value::Object(Some(addr)));
        return Ok(Some(Value::Object(Some(ia))));
    }

    // Try to parse as direct IP address first
    if hostname.parse::<std::net::Ipv4Addr>().is_ok()
        || hostname.parse::<std::net::Ipv6Addr>().is_ok()
    {
        let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
        let host = ctx.create_string(&hostname);
        let addr = ctx.create_string(&hostname);
        ctx.set_field(ia, 0, Value::Object(Some(host)));
        ctx.set_field(ia, 1, Value::Object(Some(addr)));
        return Ok(Some(Value::Object(Some(ia))));
    }

    // Real DNS resolution via std::net
    let lookup = format!("{}:0", hostname);
    if let Ok(mut addrs) = std::net::ToSocketAddrs::to_socket_addrs(&lookup.as_str()) {
        if let Some(socket_addr) = addrs.next() {
            let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
            let host = ctx.create_string(&hostname);
            let addr = ctx.create_string(&socket_addr.ip().to_string());
            ctx.set_field(ia, 0, Value::Object(Some(host)));
            ctx.set_field(ia, 1, Value::Object(Some(addr)));
            return Ok(Some(Value::Object(Some(ia))));
        }
    }

    // Resolution failed — return exception (UnknownHostException)
    Err(RuntimeError::IllegalArgumentException {
        message: format!("UnknownHostException: {}", hostname),
    }
    .into())
}

/// InetAddress.getAllByName(String) — resolve hostname to all IP addresses.
fn native_inet_get_all_by_name(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let hostname = match args.first() {
        Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
        _ => return Ok(Some(Value::Object(None))),
    };

    let lookup = if hostname.is_empty() || hostname == "localhost" {
        "localhost:0".to_string()
    } else {
        format!("{}:0", hostname)
    };

    let mut results = Vec::new();
    if let Ok(addrs) = std::net::ToSocketAddrs::to_socket_addrs(&lookup.as_str()) {
        for sa in addrs {
            let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
            let host = ctx.create_string(&hostname);
            let addr = ctx.create_string(&sa.ip().to_string());
            ctx.set_field(ia, 0, Value::Object(Some(host)));
            ctx.set_field(ia, 1, Value::Object(Some(addr)));
            results.push(ia);
        }
    }
    if results.is_empty() {
        // At least return localhost
        let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
        let host = ctx.create_string(&hostname);
        let addr = ctx.create_string("127.0.0.1");
        ctx.set_field(ia, 0, Value::Object(Some(host)));
        ctx.set_field(ia, 1, Value::Object(Some(addr)));
        results.push(ia);
    }
    let arr = ctx.new_ref_array(ClassId::new(0), results.len());
    for (i, r) in results.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Object(Some(*r)));
    }
    Ok(Some(Value::Object(Some(arr))))
}

/// Read a Java `byte[]` of length `len` into a `Vec<u8>` (sign-extending each
/// element back to its unsigned form). Used by [`native_inet_get_by_address`]
/// and the byte-array helper in [`native_inet_get_address`].
fn read_byte_array(ctx: &mut dyn NativeContext, arr: ObjectRef, len: usize) -> Vec<u8> {
    (0..len)
        .map(|i| match ctx.get_array_element(arr, i) {
            // Values come back as i32 (sign-extended from the i8 storage).
            // Cast through `i8` so 0xFF round-trips correctly.
            Value::Int(v) => (v as i8) as u8,
            _ => 0,
        })
        .collect()
}

/// InetAddress.getByAddress(byte[]) — create from raw bytes.
///
/// Accepts a 4-byte array (IPv4) or a 16-byte array (IPv6). The IPv6 path
/// previously returned a hardcoded `::1` regardless of the input bytes; this
/// version uses the actual bytes via [`std::net::Ipv6Addr::from`] so that
/// `getByAddress({0xfe, 0x80, ...})` returns an `InetAddress` whose
/// `getHostAddress()` reflects the real input.
fn native_inet_get_by_address(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let bytes_arr = match args.first() {
        Some(Value::Object(Some(a))) => *a,
        _ => return Ok(Some(Value::Object(None))),
    };
    let len = ctx.array_length(bytes_arr);
    let addr_str = if len == 4 {
        let b = read_byte_array(ctx, bytes_arr, 4);
        std::net::Ipv4Addr::new(b[0], b[1], b[2], b[3]).to_string()
    } else if len == 16 {
        let b = read_byte_array(ctx, bytes_arr, 16);
        let mut octets = [0u8; 16];
        octets.copy_from_slice(&b);
        std::net::Ipv6Addr::from(octets).to_string()
    } else {
        return Err(RuntimeError::IllegalArgumentException {
            message: format!("addr is of illegal length: {len}"),
        }
        .into());
    };
    let ia = alloc_concurrent_synthetic(ctx, "java/net/InetAddress", 2);
    let host = ctx.create_string(&addr_str);
    let addr = ctx.create_string(&addr_str);
    ctx.set_field(ia, 0, Value::Object(Some(host)));
    ctx.set_field(ia, 1, Value::Object(Some(addr)));
    Ok(Some(Value::Object(Some(ia))))
}

/// Parse the address string stored on field 1 into an `IpAddr`. Returns
/// `None` if the field is absent or not parseable.
fn inet_addr_string(ctx: &mut dyn NativeContext, this: ObjectRef) -> Option<std::net::IpAddr> {
    let s = match ctx.get_field(this, 1) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => return None,
    };
    s.parse::<std::net::IpAddr>().ok()
}

/// `InetAddress.getAddress()` — return the raw bytes (4 for IPv4, 16 for IPv6).
fn native_inet_get_address(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let ip = inet_addr_string(ctx, this).unwrap_or(std::net::IpAddr::V4(
        std::net::Ipv4Addr::new(0, 0, 0, 0),
    ));
    let bytes: Vec<u8> = match ip {
        std::net::IpAddr::V4(v4) => v4.octets().to_vec(),
        std::net::IpAddr::V6(v6) => v6.octets().to_vec(),
    };
    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Byte, bytes.len());
    for (i, b) in bytes.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Int((*b as i8) as i32));
    }
    Ok(Some(Value::Object(Some(arr))))
}

/// Map an `InetAddress` synthetic to its parsed `IpAddr`, or fall back to
/// `127.0.0.1` if the field is missing/garbled. Used by all the boolean
/// predicate helpers below so they share one parser.
fn inet_addr_or_loopback(ctx: &mut dyn NativeContext, this: ObjectRef) -> std::net::IpAddr {
    inet_addr_string(ctx, this)
        .unwrap_or(std::net::IpAddr::V4(std::net::Ipv4Addr::LOCALHOST))
}

fn native_inet_is_loopback(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let yes = inet_addr_or_loopback(ctx, this).is_loopback();
    Ok(Some(Value::Int(if yes { 1 } else { 0 })))
}

fn native_inet_is_any_local(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let yes = inet_addr_or_loopback(ctx, this).is_unspecified();
    Ok(Some(Value::Int(if yes { 1 } else { 0 })))
}

fn native_inet_is_link_local(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let yes = match inet_addr_or_loopback(ctx, this) {
        // 169.254.0.0/16 (RFC 3927)
        std::net::IpAddr::V4(v4) => v4.is_link_local(),
        // fe80::/10 (RFC 4291)
        std::net::IpAddr::V6(v6) => {
            let segs = v6.segments();
            (segs[0] & 0xffc0) == 0xfe80
        }
    };
    Ok(Some(Value::Int(if yes { 1 } else { 0 })))
}

fn native_inet_is_site_local(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let yes = match inet_addr_or_loopback(ctx, this) {
        // RFC 1918 private blocks
        std::net::IpAddr::V4(v4) => v4.is_private(),
        // fec0::/10 (deprecated by RFC 3879 but still recognized by Java)
        std::net::IpAddr::V6(v6) => {
            let segs = v6.segments();
            (segs[0] & 0xffc0) == 0xfec0
        }
    };
    Ok(Some(Value::Int(if yes { 1 } else { 0 })))
}

fn native_inet_is_multicast(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let yes = match inet_addr_or_loopback(ctx, this) {
        std::net::IpAddr::V4(v4) => v4.is_multicast(),
        std::net::IpAddr::V6(v6) => v6.is_multicast(),
    };
    Ok(Some(Value::Int(if yes { 1 } else { 0 })))
}

/// `InetAddress.isReachable(int timeout_ms)` — best-effort reachability probe.
///
/// Real ICMP echo requires a privileged raw socket on every supported OS, so
/// instead we mirror what the OpenJDK `Inet*AddressImpl.isReachable` falls
/// back to when ICMP is unavailable: a TCP connect to port 7 (the historic
/// echo service). If port 7 fails or the OS returns ECONNREFUSED, we treat a
/// `Connection refused` as **reachable** (the host responded), which matches
/// HotSpot's behavior. Any other error / timeout is treated as not reachable.
fn native_inet_is_reachable(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let timeout_ms = args.get(1).and_then(|v| v.as_int()).unwrap_or(0);
    let timeout = if timeout_ms > 0 {
        std::time::Duration::from_millis(timeout_ms as u64)
    } else {
        std::time::Duration::from_secs(1)
    };
    let ip = match inet_addr_string(ctx, this) {
        Some(ip) => ip,
        None => return Ok(Some(Value::Int(0))),
    };
    // Loopback and any-local are always trivially reachable.
    if ip.is_loopback() || ip.is_unspecified() {
        return Ok(Some(Value::Int(1)));
    }
    // Try TCP connect to port 7 (echo). A successful connect or a
    // ConnectionRefused both indicate the host is up.
    let target = std::net::SocketAddr::new(ip, 7);
    match std::net::TcpStream::connect_timeout(&target, timeout) {
        Ok(_) => Ok(Some(Value::Int(1))),
        Err(e) if e.kind() == std::io::ErrorKind::ConnectionRefused => {
            Ok(Some(Value::Int(1)))
        }
        Err(_) => Ok(Some(Value::Int(0))),
    }
}

// ===========================================================================
// Phase 31: java.util.logging + java.util.Locale
// ===========================================================================

fn register_logging_natives(registry: &mut NativeMethodRegistry) {
    let logger = "java/util/logging/Logger";
    let level = "java/util/logging/Level";

    // Logger = 2-field synthetic (name, level)
    registry.register(
        logger,
        "getLogger",
        "(Ljava/lang/String;)Ljava/util/logging/Logger;",
        native_logger_get,
    );
    registry.register(
        logger,
        "getGlobal",
        "()Ljava/util/logging/Logger;",
        native_logger_get_global,
    );
    registry.register(
        logger,
        "getName",
        "()Ljava/lang/String;",
        native_logger_get_name,
    );
    // Level-aware logging methods. SEVERE=1000, WARNING=900, INFO=800,
    // CONFIG=700, FINE=500, FINER=400, FINEST=300. A message is logged if the
    // logger's current level <= the method's level.
    registry.register(logger, "info", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 800)
    });
    registry.register(logger, "warning", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 900)
    });
    registry.register(logger, "severe", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 1000)
    });
    registry.register(logger, "fine", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 500)
    });
    registry.register(logger, "finer", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 400)
    });
    registry.register(logger, "finest", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 300)
    });
    registry.register(logger, "config", "(Ljava/lang/String;)V", |ctx, args| {
        native_logger_log_if(ctx, args, 700)
    });
    registry.register(
        logger,
        "setLevel",
        "(Ljava/util/logging/Level;)V",
        |ctx, args| {
            let this = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(None),
            };
            let level = args.get(1).copied().unwrap_or(Value::Object(None));
            ctx.set_field(this, LOGGER_FIELD_LEVEL, level);
            Ok(None)
        },
    );
    registry.register(
        logger,
        "getLevel",
        "()Ljava/util/logging/Level;",
        native_logger_get_level,
    );
    registry.register(
        logger,
        "isLoggable",
        "(Ljava/util/logging/Level;)Z",
        |ctx, args| {
            let this = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Int(1))),
            };
            let arg_val = match args.get(1) {
                Some(Value::Object(Some(l))) => ctx.get_field(*l, 1).as_int().unwrap_or(800),
                _ => 800,
            };
            let current = match ctx.get_field(this, LOGGER_FIELD_LEVEL) {
                Value::Object(Some(l)) => ctx.get_field(l, 1).as_int().unwrap_or(800),
                _ => 800, // default INFO
            };
            // A message is loggable if its level >= logger's current level
            Ok(Some(Value::Int(if arg_val >= current { 1 } else { 0 })))
        },
    );
    registry.register(
        logger,
        "log",
        "(Ljava/util/logging/Level;Ljava/lang/String;)V",
        native_logger_log_level,
    );

    // Level constants
    registry.register(
        level,
        "ALL",
        "()Ljava/util/logging/Level;",
        native_level_all,
    );
    registry.register(
        level,
        "SEVERE",
        "()Ljava/util/logging/Level;",
        native_level_severe,
    );
    registry.register(
        level,
        "WARNING",
        "()Ljava/util/logging/Level;",
        native_level_warning,
    );
    registry.register(
        level,
        "INFO",
        "()Ljava/util/logging/Level;",
        native_level_info,
    );
    registry.register(
        level,
        "CONFIG",
        "()Ljava/util/logging/Level;",
        native_level_config,
    );
    registry.register(
        level,
        "FINE",
        "()Ljava/util/logging/Level;",
        native_level_fine,
    );
    registry.register(
        level,
        "FINER",
        "()Ljava/util/logging/Level;",
        native_level_finer,
    );
    registry.register(
        level,
        "FINEST",
        "()Ljava/util/logging/Level;",
        native_level_finest,
    );
    registry.register(
        level,
        "OFF",
        "()Ljava/util/logging/Level;",
        native_level_off,
    );
    registry.register(
        level,
        "getName",
        "()Ljava/lang/String;",
        native_level_get_name,
    );
    registry.register(level, "intValue", "()I", native_level_int_value);
    registry.register(
        level,
        "toString",
        "()Ljava/lang/String;",
        native_level_get_name,
    );
}

const LOGGER_FIELD_NAME: usize = 0;
const LOGGER_FIELD_LEVEL: usize = 1;
const LEVEL_FIELD_NAME: usize = 0;
const LEVEL_FIELD_VALUE: usize = 1;

fn alloc_level(ctx: &mut dyn NativeContext, name: &str, value: i32) -> ObjectRef {
    let lvl = alloc_concurrent_synthetic(ctx, "java/util/logging/Level", 2);
    let n = ctx.create_string(name);
    ctx.set_field(lvl, LEVEL_FIELD_NAME, Value::Object(Some(n)));
    ctx.set_field(lvl, LEVEL_FIELD_VALUE, Value::Int(value));
    lvl
}

fn native_logger_get(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let logger = alloc_concurrent_synthetic(ctx, "java/util/logging/Logger", 2);
    ctx.set_field(
        logger,
        LOGGER_FIELD_NAME,
        args.first().copied().unwrap_or(Value::Object(None)),
    );
    let info = alloc_level(ctx, "INFO", 800);
    ctx.set_field(logger, LOGGER_FIELD_LEVEL, Value::Object(Some(info)));
    Ok(Some(Value::Object(Some(logger))))
}

fn native_logger_get_global(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    let name = ctx.create_string("global");
    let logger = alloc_concurrent_synthetic(ctx, "java/util/logging/Logger", 2);
    ctx.set_field(logger, LOGGER_FIELD_NAME, Value::Object(Some(name)));
    let info = alloc_level(ctx, "INFO", 800);
    ctx.set_field(logger, LOGGER_FIELD_LEVEL, Value::Object(Some(info)));
    Ok(Some(Value::Object(Some(logger))))
}

fn native_logger_get_name(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, LOGGER_FIELD_NAME)))
}

fn native_logger_get_level(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, LOGGER_FIELD_LEVEL)))
}

fn native_logger_log(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // Print the log message
    if let Some(Value::Object(Some(msg))) = args.get(1) {
        if let Some(s) = ctx.read_string(*msg) {
            ctx.record_printed_line(s);
        }
    }
    Ok(None)
}

/// Log a message only if the logger's current level allows `method_level`.
/// Compares current level (read from LOGGER_FIELD_LEVEL field 1) against the
/// method's inherent level (SEVERE=1000 .. FINEST=300).
fn native_logger_log_if(
    ctx: &mut dyn NativeContext,
    args: &[Value],
    method_level: i32,
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let current = match ctx.get_field(this, LOGGER_FIELD_LEVEL) {
        Value::Object(Some(l)) => ctx.get_field(l, LEVEL_FIELD_VALUE).as_int().unwrap_or(800),
        _ => 800, // default INFO
    };
    if method_level < current {
        return Ok(None); // filter out — level is below logger threshold
    }
    if let Some(Value::Object(Some(msg))) = args.get(1) {
        if let Some(s) = ctx.read_string(*msg) {
            ctx.record_printed_line(s);
        }
    }
    Ok(None)
}

fn native_logger_log_level(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args: this, level, message
    if let Some(Value::Object(Some(msg))) = args.get(2) {
        if let Some(s) = ctx.read_string(*msg) {
            ctx.record_printed_line(s);
        }
    }
    Ok(None)
}

fn native_level_all(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "ALL", i32::MIN)))))
}
fn native_level_severe(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "SEVERE", 1000)))))
}
fn native_level_warning(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "WARNING", 900)))))
}
fn native_level_info(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "INFO", 800)))))
}
fn native_level_config(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "CONFIG", 700)))))
}
fn native_level_fine(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "FINE", 500)))))
}
fn native_level_finer(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "FINER", 400)))))
}
fn native_level_finest(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "FINEST", 300)))))
}
fn native_level_off(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(alloc_level(ctx, "OFF", i32::MAX)))))
}

fn native_level_get_name(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, LEVEL_FIELD_NAME)))
}

fn native_level_int_value(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    Ok(Some(ctx.get_field(this, LEVEL_FIELD_VALUE)))
}

// ===========================================================================
// SLF4J Logging Facade — bridges to console output
// ===========================================================================

// SLF4J Logger: 2-field synthetic (name=0, level=1 where 0=TRACE..4=ERROR)
const SLF4J_NAME: usize = 0;
const SLF4J_LEVEL: usize = 1;

// MDC (Mapped Diagnostic Context) backed by thread-local storage
std::thread_local! {
    static MDC_MAP: std::cell::RefCell<std::collections::HashMap<String, String>> = std::cell::RefCell::new(std::collections::HashMap::new());
}

fn register_slf4j_natives(registry: &mut NativeMethodRegistry) {
    let lf = "org/slf4j/LoggerFactory";

    // LoggerFactory.getLogger(String) → Logger
    registry.register(lf, "getLogger", "(Ljava/lang/String;)Lorg/slf4j/Logger;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let logger = alloc_concurrent_synthetic(ctx, "org/slf4j/Logger", 2);
        ctx.set_field(logger, SLF4J_NAME, name);
        ctx.set_field(logger, SLF4J_LEVEL, Value::Int(1)); // default: DEBUG
        Ok(Some(Value::Object(Some(logger))))
    });

    // LoggerFactory.getLogger(Class) → Logger
    registry.register(lf, "getLogger", "(Ljava/lang/Class;)Lorg/slf4j/Logger;", |ctx, args| {
        // Extract class name from the Class mirror
        let name_val = match args.first() {
            Some(Value::Object(Some(class_mirror))) => {
                match ctx.get_field(*class_mirror, 0) {
                    Value::Object(Some(n)) => Value::Object(Some(n)),
                    _ => {
                        let s = ctx.create_string("unknown");
                        Value::Object(Some(s))
                    }
                }
            }
            _ => {
                let s = ctx.create_string("unknown");
                Value::Object(Some(s))
            }
        };
        let logger = alloc_concurrent_synthetic(ctx, "org/slf4j/Logger", 2);
        ctx.set_field(logger, SLF4J_NAME, name_val);
        ctx.set_field(logger, SLF4J_LEVEL, Value::Int(1)); // DEBUG
        Ok(Some(Value::Object(Some(logger))))
    });

    // LoggerFactory.getILoggerFactory() → ILoggerFactory
    registry.register(lf, "getILoggerFactory", "()Lorg/slf4j/ILoggerFactory;", |ctx, _| {
        let factory = alloc_concurrent_synthetic(ctx, "org/slf4j/ILoggerFactory", 0);
        Ok(Some(Value::Object(Some(factory))))
    });

    let lg = "org/slf4j/Logger";

    // Logger.getName() → String
    registry.register(lg, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, SLF4J_NAME)))
    });

    // Logging methods: trace, debug, info, warn, error
    // trace(String) — instance method; SLF4J TRACE level is below the
    // default threshold so trace() intentionally discards its arguments.
    // NEW-6: documented with the _with_this form so the intent is clear.
    registry.register(lg, "trace", "(Ljava/lang/String;)V", native_noop_with_this);
    registry.register(lg, "trace", "(Ljava/lang/String;Ljava/lang/Object;)V", native_noop_with_this);
    registry.register(lg, "trace", "(Ljava/lang/String;Ljava/lang/Object;Ljava/lang/Object;)V", native_noop_with_this);
    registry.register(lg, "trace", "(Ljava/lang/String;[Ljava/lang/Object;)V", native_noop_with_this);

    // debug(String)
    registry.register(lg, "debug", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lg, "debug", "(Ljava/lang/String;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "debug", "(Ljava/lang/String;Ljava/lang/Object;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "debug", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);

    // info(String)
    registry.register(lg, "info", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lg, "info", "(Ljava/lang/String;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "info", "(Ljava/lang/String;Ljava/lang/Object;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "info", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);

    // warn(String)
    registry.register(lg, "warn", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lg, "warn", "(Ljava/lang/String;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "warn", "(Ljava/lang/String;Ljava/lang/Object;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "warn", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "warn", "(Ljava/lang/String;Ljava/lang/Throwable;)V", slf4j_log_msg);

    // error(String)
    registry.register(lg, "error", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lg, "error", "(Ljava/lang/String;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "error", "(Ljava/lang/String;Ljava/lang/Object;Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "error", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(lg, "error", "(Ljava/lang/String;Ljava/lang/Throwable;)V", slf4j_log_msg);

    // Level checks — consult the stored level (0=TRACE, 1=DEBUG, 2=INFO, 3=WARN, 4=ERROR)
    registry.register(lg, "isTraceEnabled", "()Z", |ctx, args| {
        let level = match args.first() {
            Some(Value::Object(Some(this))) => ctx.get_field(*this, SLF4J_LEVEL).as_int().unwrap_or(1),
            _ => 1,
        };
        Ok(Some(Value::Int(if level <= 0 { 1 } else { 0 })))
    });
    registry.register(lg, "isDebugEnabled", "()Z", |ctx, args| {
        let level = match args.first() {
            Some(Value::Object(Some(this))) => ctx.get_field(*this, SLF4J_LEVEL).as_int().unwrap_or(1),
            _ => 1,
        };
        Ok(Some(Value::Int(if level <= 1 { 1 } else { 0 })))
    });
    registry.register(lg, "isInfoEnabled", "()Z", |ctx, args| {
        let level = match args.first() {
            Some(Value::Object(Some(this))) => ctx.get_field(*this, SLF4J_LEVEL).as_int().unwrap_or(1),
            _ => 1,
        };
        Ok(Some(Value::Int(if level <= 2 { 1 } else { 0 })))
    });
    registry.register(lg, "isWarnEnabled", "()Z", |ctx, args| {
        let level = match args.first() {
            Some(Value::Object(Some(this))) => ctx.get_field(*this, SLF4J_LEVEL).as_int().unwrap_or(1),
            _ => 1,
        };
        Ok(Some(Value::Int(if level <= 3 { 1 } else { 0 })))
    });
    registry.register(lg, "isErrorEnabled", "()Z", |ctx, args| {
        let level = match args.first() {
            Some(Value::Object(Some(this))) => ctx.get_field(*this, SLF4J_LEVEL).as_int().unwrap_or(1),
            _ => 1,
        };
        Ok(Some(Value::Int(if level <= 4 { 1 } else { 0 })))
    });

    // MDC (Mapped Diagnostic Context) — backed by thread-local HashMap
    let mdc = "org/slf4j/MDC";
    registry.register(mdc, "put", "(Ljava/lang/String;Ljava/lang/String;)V", |ctx, args| {
        let key = match args.first() {
            Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
            _ => return Ok(None),
        };
        let value = match args.get(1) {
            Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
            _ => return Ok(None),
        };
        MDC_MAP.with(|m| m.borrow_mut().insert(key, value));
        Ok(None)
    });
    registry.register(mdc, "get", "(Ljava/lang/String;)Ljava/lang/String;", |ctx, args| {
        let key = match args.first() {
            Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
            _ => return Ok(Some(Value::Object(None))),
        };
        let value = MDC_MAP.with(|m| m.borrow().get(&key).cloned());
        match value {
            Some(v) => Ok(Some(Value::Object(Some(ctx.create_string(&v))))),
            None => Ok(Some(Value::Object(None))),
        }
    });
    registry.register(mdc, "remove", "(Ljava/lang/String;)V", |ctx, args| {
        let key = match args.first() {
            Some(Value::Object(Some(s))) => ctx.read_string(*s).unwrap_or_default(),
            _ => return Ok(None),
        };
        MDC_MAP.with(|m| m.borrow_mut().remove(&key));
        Ok(None)
    });
    registry.register(mdc, "clear", "()V", |_ctx, _args| {
        MDC_MAP.with(|m| m.borrow_mut().clear());
        Ok(None)
    });
    registry.register(mdc, "getCopyOfContextMap", "()Ljava/util/Map;", |ctx, _args| {
        // Snapshot the thread-local MDC map into a fresh HashMap.
        let snapshot: Vec<(String, String)> =
            MDC_MAP.with(|m| m.borrow().iter().map(|(k, v)| (k.clone(), v.clone())).collect());
        if snapshot.is_empty() {
            return Ok(Some(Value::Object(None)));
        }
        let map = alloc_concurrent_synthetic(ctx, "java/util/HashMap", 3);
        rustjvm_native_collections::native_map_init(ctx, &[Value::Object(Some(map))]).ok();
        for (k, v) in snapshot {
            let key_obj = ctx.create_string(&k);
            let val_obj = ctx.create_string(&v);
            rustjvm_native_collections::native_map_put_pub(
                ctx,
                &[
                    Value::Object(Some(map)),
                    Value::Object(Some(key_obj)),
                    Value::Object(Some(val_obj)),
                ],
            )
            .ok();
        }
        Ok(Some(Value::Object(Some(map))))
    });
    registry.register(mdc, "setContextMap", "(Ljava/util/Map;)V", |ctx, args| {
        // Replace the thread-local MDC map with the entries from the provided Map.
        // Step 1: clear current MDC.
        MDC_MAP.with(|m| m.borrow_mut().clear());
        // Step 2: if arg is non-null, iterate keys and copy entries.
        let map = match args.first() {
            Some(Value::Object(Some(m))) => *m,
            _ => return Ok(None),
        };
        // Get key set
        let key_set = match rustjvm_native_collections::native_map_key_set_pub(
            ctx,
            &[Value::Object(Some(map))],
        ) {
            Ok(Some(Value::Object(Some(s)))) => s,
            _ => return Ok(None),
        };
        // Convert set to array via toArray (HashSet has 1-field backing array structure).
        // Iterate the set's backing storage instead by getting size first.
        let size_val = rustjvm_native_collections::native_map_size_pub(
            ctx,
            &[Value::Object(Some(map))],
        );
        let size = match size_val {
            Ok(Some(Value::Int(n))) => n,
            _ => 0,
        };
        if size == 0 {
            return Ok(None);
        }
        // The key_set is a HashSet — convert to array by trying its toArray method.
        let arr_result = ctx.invoke_virtual(
            key_set,
            "toArray",
            "()[Ljava/lang/Object;",
            &[],
        );
        let arr = match arr_result {
            Ok(Some(Value::Object(Some(a)))) => a,
            _ => return Ok(None),
        };
        let arr_len = ctx.array_length(arr);
        for i in 0..arr_len {
            let key_val = ctx.get_array_element(arr, i);
            let key_obj = match key_val {
                Value::Object(Some(o)) => o,
                _ => continue,
            };
            let key_str = ctx.read_string(key_obj).unwrap_or_default();
            // Get value via map.get(key)
            let val_result = rustjvm_native_collections::native_map_get_pub(
                ctx,
                &[Value::Object(Some(map)), Value::Object(Some(key_obj))],
            );
            let val_str = match val_result {
                Ok(Some(Value::Object(Some(v)))) => ctx.read_string(v).unwrap_or_default(),
                _ => String::new(),
            };
            MDC_MAP.with(|m| m.borrow_mut().insert(key_str, val_str));
        }
        Ok(None)
    });

    // Marker — Spring Boot sometimes uses markers
    let marker = "org/slf4j/MarkerFactory";
    registry.register(marker, "getMarker", "(Ljava/lang/String;)Lorg/slf4j/Marker;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let m = alloc_concurrent_synthetic(ctx, "org/slf4j/Marker", 1);
        ctx.set_field(m, 0, name);
        Ok(Some(Value::Object(Some(m))))
    });

    // --- java.util.logging (JUL) — standard JDK logging ---
    let jul_logger = "java/util/logging/Logger";
    registry.register(jul_logger, "getLogger", "(Ljava/lang/String;)Ljava/util/logging/Logger;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let logger = alloc_concurrent_synthetic(ctx, "java/util/logging/Logger", 2);
        ctx.set_field(logger, 0, name);
        ctx.set_field(logger, 1, Value::Int(800)); // INFO level
        Ok(Some(Value::Object(Some(logger))))
    });
    registry.register(jul_logger, "getGlobal", "()Ljava/util/logging/Logger;", |ctx, _| {
        let name = ctx.create_string("global");
        let logger = alloc_concurrent_synthetic(ctx, "java/util/logging/Logger", 2);
        ctx.set_field(logger, 0, Value::Object(Some(name)));
        ctx.set_field(logger, 1, Value::Int(800));
        Ok(Some(Value::Object(Some(logger))))
    });
    registry.register(jul_logger, "info", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "warning", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "severe", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "fine", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "finer", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "finest", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "config", "(Ljava/lang/String;)V", jul_log_msg);
    registry.register(jul_logger, "log", "(Ljava/util/logging/Level;Ljava/lang/String;)V", |ctx, args| {
        if let Some(Value::Object(Some(msg))) = args.get(2) {
            if let Some(s) = ctx.read_string(*msg) {
                ctx.record_printed_line(format!("[JUL] {}", s));
            }
        }
        Ok(None)
    });
    registry.register(jul_logger, "isLoggable", "(Ljava/util/logging/Level;)Z", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let logger_level = ctx.get_field(this, 1).as_int().unwrap_or(800);
        let check_level = match args.get(1) {
            Some(Value::Object(Some(lvl))) => ctx.get_field(*lvl, 1).as_int().unwrap_or(800),
            _ => 800,
        };
        Ok(Some(Value::Int(if check_level >= logger_level { 1 } else { 0 })))
    });
    registry.register(jul_logger, "setLevel", "(Ljava/util/logging/Level;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let level_val = match args.get(1) {
            Some(Value::Object(Some(lvl))) => ctx.get_field(*lvl, 1).as_int().unwrap_or(800),
            _ => 800,
        };
        ctx.set_field(this, 1, Value::Int(level_val));
        Ok(None)
    });
    registry.register(jul_logger, "getLevel", "()Ljava/util/logging/Level;", |ctx, _| {
        let level = alloc_concurrent_synthetic(ctx, "java/util/logging/Level", 2);
        let name = ctx.create_string("INFO");
        ctx.set_field(level, 0, Value::Object(Some(name)));
        ctx.set_field(level, 1, Value::Int(800));
        Ok(Some(Value::Object(Some(level))))
    });
    registry.register(jul_logger, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    registry.register(jul_logger, "addHandler", "(Ljava/util/logging/Handler;)V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        let handler = args.get(1).copied().unwrap_or(Value::Object(None));
        // Logger comment in phases_late.rs: field 2 = handlers ArrayList. Some allocations
        // only create 2 fields, so guard with object_num_fields.
        if ctx.object_num_fields(this) > 2 {
            // Lazily initialise the handlers ArrayList if absent.
            let handlers = match ctx.get_field(this, 2) {
                Value::Object(Some(lst)) => lst,
                _ => {
                    let lst = alloc_concurrent_synthetic(ctx, "java/util/ArrayList", 2);
                    rustjvm_native_collections::native_al_init(ctx, &[Value::Object(Some(lst))]).ok();
                    ctx.set_field(this, 2, Value::Object(Some(lst)));
                    lst
                }
            };
            rustjvm_native_collections::native_al_add(
                ctx,
                &[Value::Object(Some(handlers)), handler],
            )
            .ok();
        }
        Ok(None)
    });
    registry.register(jul_logger, "removeHandler", "(Ljava/util/logging/Handler;)V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        let handler = args.get(1).copied().unwrap_or(Value::Object(None));
        if ctx.object_num_fields(this) > 2 {
            if let Value::Object(Some(handlers)) = ctx.get_field(this, 2) {
                rustjvm_native_collections::native_al_remove_obj(
                    ctx,
                    &[Value::Object(Some(handlers)), handler],
                )
                .ok();
            }
        }
        Ok(None)
    });

    // java.util.logging.Level
    let level = "java/util/logging/Level";
    registry.register(level, "parse", "(Ljava/lang/String;)Ljava/util/logging/Level;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let lvl = alloc_concurrent_synthetic(ctx, "java/util/logging/Level", 2);
        ctx.set_field(lvl, 0, name);
        ctx.set_field(lvl, 1, Value::Int(800));
        Ok(Some(Value::Object(Some(lvl))))
    });

    // java.util.logging.LogManager
    let lm = "java/util/logging/LogManager";
    registry.register(lm, "getLogManager", "()Ljava/util/logging/LogManager;", |ctx, _| {
        let mgr = alloc_concurrent_synthetic(ctx, "java/util/logging/LogManager", 0);
        Ok(Some(Value::Object(Some(mgr))))
    });
    registry.register(lm, "getLogger", "(Ljava/lang/String;)Ljava/util/logging/Logger;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let logger = alloc_concurrent_synthetic(ctx, "java/util/logging/Logger", 2);
        ctx.set_field(logger, 0, name);
        ctx.set_field(logger, 1, Value::Int(800));
        Ok(Some(Value::Object(Some(logger))))
    });

    // --- Apache Commons Logging ---
    let acl = "org/apache/commons/logging/LogFactory";
    registry.register(acl, "getLog", "(Ljava/lang/Class;)Lorg/apache/commons/logging/Log;", |ctx, _| {
        let log = alloc_concurrent_synthetic(ctx, "org/apache/commons/logging/Log", 1);
        ctx.set_field(log, 0, Value::Int(1)); // enabled
        Ok(Some(Value::Object(Some(log))))
    });
    registry.register(acl, "getLog", "(Ljava/lang/String;)Lorg/apache/commons/logging/Log;", |ctx, _| {
        let log = alloc_concurrent_synthetic(ctx, "org/apache/commons/logging/Log", 1);
        ctx.set_field(log, 0, Value::Int(1));
        Ok(Some(Value::Object(Some(log))))
    });
    let acl_log = "org/apache/commons/logging/Log";
    registry.register(acl_log, "info", "(Ljava/lang/Object;)V", |ctx, args| {
        if let Some(Value::Object(Some(msg))) = args.get(1) {
            if let Some(s) = ctx.read_string(*msg) { ctx.record_printed_line(format!("[ACL] {}", s)); }
        }
        Ok(None)
    });
    // Commons-Logging debug — instance method, below default threshold
    // so we discard arguments. NEW-6.
    registry.register(acl_log, "debug", "(Ljava/lang/Object;)V", native_noop_with_this);
    registry.register(acl_log, "warn", "(Ljava/lang/Object;)V", |ctx, args| {
        if let Some(Value::Object(Some(msg))) = args.get(1) {
            if let Some(s) = ctx.read_string(*msg) { ctx.record_printed_line(format!("[ACL WARN] {}", s)); }
        }
        Ok(None)
    });
    registry.register(acl_log, "error", "(Ljava/lang/Object;)V", |ctx, args| {
        if let Some(Value::Object(Some(msg))) = args.get(1) {
            if let Some(s) = ctx.read_string(*msg) { ctx.record_printed_line(format!("[ACL ERROR] {}", s)); }
        }
        Ok(None)
    });
    registry.register(acl_log, "isDebugEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(acl_log, "isInfoEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(acl_log, "isWarnEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(acl_log, "isErrorEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));

    // --- Log4j2 (org.apache.logging.log4j) ---
    let log4j_lm = "org/apache/logging/log4j/LogManager";
    registry.register(log4j_lm, "getLogger", "(Ljava/lang/Class;)Lorg/apache/logging/log4j/Logger;", |ctx, args| {
        let name_val = match args.first() {
            Some(Value::Object(Some(mirror))) => {
                match ctx.get_field(*mirror, 0) {
                    Value::Object(Some(n)) => Value::Object(Some(n)),
                    _ => { let s = ctx.create_string("unknown"); Value::Object(Some(s)) }
                }
            }
            _ => { let s = ctx.create_string("unknown"); Value::Object(Some(s)) }
        };
        let logger = alloc_concurrent_synthetic(ctx, "org/apache/logging/log4j/Logger", 2);
        ctx.set_field(logger, 0, name_val);
        ctx.set_field(logger, 1, Value::Int(2)); // INFO
        Ok(Some(Value::Object(Some(logger))))
    });
    registry.register(log4j_lm, "getLogger", "(Ljava/lang/String;)Lorg/apache/logging/log4j/Logger;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let logger = alloc_concurrent_synthetic(ctx, "org/apache/logging/log4j/Logger", 2);
        ctx.set_field(logger, 0, name);
        ctx.set_field(logger, 1, Value::Int(2)); // INFO
        Ok(Some(Value::Object(Some(logger))))
    });
    registry.register(log4j_lm, "getRootLogger", "()Lorg/apache/logging/log4j/Logger;", |ctx, _| {
        let name = ctx.create_string("ROOT");
        let logger = alloc_concurrent_synthetic(ctx, "org/apache/logging/log4j/Logger", 2);
        ctx.set_field(logger, 0, Value::Object(Some(name)));
        ctx.set_field(logger, 1, Value::Int(2));
        Ok(Some(Value::Object(Some(logger))))
    });

    let log4j_lg = "org/apache/logging/log4j/Logger";
    // Log4j2 trace — instance method, below default threshold. NEW-6.
    registry.register(log4j_lg, "trace", "(Ljava/lang/String;)V", native_noop_with_this);
    registry.register(log4j_lg, "trace", "(Ljava/lang/String;[Ljava/lang/Object;)V", native_noop_with_this);
    registry.register(log4j_lg, "debug", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(log4j_lg, "debug", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(log4j_lg, "info", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(log4j_lg, "info", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(log4j_lg, "warn", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(log4j_lg, "warn", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(log4j_lg, "error", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(log4j_lg, "error", "(Ljava/lang/String;[Ljava/lang/Object;)V", slf4j_log_msg);
    registry.register(log4j_lg, "error", "(Ljava/lang/String;Ljava/lang/Throwable;)V", slf4j_log_msg);
    registry.register(log4j_lg, "fatal", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(log4j_lg, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    registry.register(log4j_lg, "isTraceEnabled", "()Z", |_, _| Ok(Some(Value::Int(0))));
    registry.register(log4j_lg, "isDebugEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(log4j_lg, "isInfoEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(log4j_lg, "isWarnEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(log4j_lg, "isErrorEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));

    // --- Logback (ch.qos.logback) ---
    let lb_factory = "ch/qos/logback/classic/LoggerContext";
    // LoggerContext constructor — no fields to initialize. NEW-6.
    registry.register(lb_factory, "<init>", "()V", native_noop_with_this);
    registry.register(lb_factory, "getLogger", "(Ljava/lang/String;)Lch/qos/logback/classic/Logger;", |ctx, args| {
        let name = args.first().copied().unwrap_or(Value::Object(None));
        let logger = alloc_concurrent_synthetic(ctx, "ch/qos/logback/classic/Logger", 2);
        ctx.set_field(logger, 0, name);
        ctx.set_field(logger, 1, Value::Int(1)); // DEBUG
        Ok(Some(Value::Object(Some(logger))))
    });

    let lb_logger = "ch/qos/logback/classic/Logger";
    registry.register(lb_logger, "debug", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lb_logger, "info", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lb_logger, "warn", "(Ljava/lang/String;)V", slf4j_log_msg);
    registry.register(lb_logger, "error", "(Ljava/lang/String;)V", slf4j_log_msg);
    // Logback trace — below default threshold, discard args. NEW-6.
    registry.register(lb_logger, "trace", "(Ljava/lang/String;)V", native_noop_with_this);
    registry.register(lb_logger, "getName", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0)))
    });
    // setLevel — instance setter; our synthetic logger doesn't track
    // per-instance level beyond its initial value. NEW-6.
    registry.register(lb_logger, "setLevel", "(Lch/qos/logback/classic/Level;)V", native_noop_with_this);
    registry.register(lb_logger, "isDebugEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
    registry.register(lb_logger, "isInfoEnabled", "()Z", |_, _| Ok(Some(Value::Int(1))));
}

fn slf4j_log_msg(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args[0] = this (Logger), args[1] = format string, args[2..] = params
    let logger_name = match args.first() {
        Some(Value::Object(Some(this))) => {
            match ctx.get_field(*this, SLF4J_NAME) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            }
        }
        _ => String::new(),
    };

    let format_str = match args.get(1) {
        Some(Value::Object(Some(msg))) => ctx.read_string(*msg).unwrap_or_default(),
        _ => return Ok(None),
    };

    // Substitute {} placeholders with parameter values
    let mut result = format_str.clone();
    let mut param_idx = 2;
    while let Some(pos) = result.find("{}") {
        let replacement = match args.get(param_idx) {
            Some(Value::Object(Some(obj))) => ctx.read_string(*obj).unwrap_or_else(|| format!("Object@{:x}", param_idx)),
            Some(Value::Object(None)) => "null".to_string(),
            Some(Value::Int(v)) => v.to_string(),
            Some(Value::Long(v)) => v.to_string(),
            Some(Value::Float(v)) => format!("{}", v),
            Some(Value::Double(v)) => format!("{}", v),
            _ => break,
        };
        result = format!("{}{}{}", &result[..pos], replacement, &result[pos + 2..]);
        param_idx += 1;
    }

    // Format as: [LEVEL] logger - message
    let short_name = logger_name.rsplit('.').next().unwrap_or(&logger_name);
    let formatted = format!("[LOG] {} - {}", short_name, result);
    ctx.record_printed_line(formatted);
    Ok(None)
}

/// java.util.logging (JUL) log message handler.
fn jul_log_msg(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // args[0] = this (Logger), args[1] = message string
    let logger_name = match args.first() {
        Some(Value::Object(Some(this))) => {
            match ctx.get_field(*this, 0) {
                Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
                _ => String::new(),
            }
        }
        _ => String::new(),
    };
    if let Some(Value::Object(Some(msg))) = args.get(1) {
        if let Some(s) = ctx.read_string(*msg) {
            let short = logger_name.rsplit('.').next().unwrap_or(&logger_name);
            ctx.record_printed_line(format!("[JUL] {} - {}", short, s));
        }
    }
    Ok(None)
}

fn register_locale_natives(registry: &mut NativeMethodRegistry) {
    let loc = "java/util/Locale";

    // Locale = 3-field synthetic (language, country, variant)
    registry.register(loc, "<init>", "(Ljava/lang/String;)V", native_locale_init);
    registry.register(
        loc,
        "<init>",
        "(Ljava/lang/String;Ljava/lang/String;)V",
        native_locale_init2,
    );
    registry.register(
        loc,
        "getDefault",
        "()Ljava/util/Locale;",
        native_locale_get_default,
    );
    registry.register(
        loc,
        "getLanguage",
        "()Ljava/lang/String;",
        native_locale_get_lang,
    );
    registry.register(
        loc,
        "getCountry",
        "()Ljava/lang/String;",
        native_locale_get_country,
    );
    registry.register(
        loc,
        "toString",
        "()Ljava/lang/String;",
        native_locale_to_string,
    );
    registry.register(
        loc,
        "toLanguageTag",
        "()Ljava/lang/String;",
        native_locale_to_tag,
    );
    registry.register(loc, "equals", "(Ljava/lang/Object;)Z", native_locale_equals);
    registry.register(loc, "hashCode", "()I", native_locale_hash_code);
    registry.register(loc, "toString", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        let lang = match ctx.get_field(this, 0) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let country = match ctx.get_field(this, 1) {
            Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
            _ => String::new(),
        };
        let result = if country.is_empty() {
            lang
        } else {
            format!("{}_{}", lang, country)
        };
        Ok(Some(Value::Object(Some(ctx.create_string(&result)))))
    });

    // Static constants
    registry.register(
        loc,
        "ENGLISH",
        "()Ljava/util/Locale;",
        native_locale_english,
    );
    registry.register(loc, "US", "()Ljava/util/Locale;", native_locale_us);
    registry.register(loc, "UK", "()Ljava/util/Locale;", native_locale_uk);
    registry.register(loc, "ROOT", "()Ljava/util/Locale;", native_locale_root);
    registry.register(loc, "FRENCH", "()Ljava/util/Locale;", |ctx, _args| {
        let s1 = ctx.create_string("fr"); let s2 = ctx.create_string("");
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        ctx.set_field(l, 0, Value::Object(Some(s1))); ctx.set_field(l, 1, Value::Object(Some(s2)));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "GERMAN", "()Ljava/util/Locale;", |ctx, _args| {
        let s1 = ctx.create_string("de"); let s2 = ctx.create_string("");
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        ctx.set_field(l, 0, Value::Object(Some(s1))); ctx.set_field(l, 1, Value::Object(Some(s2)));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "JAPAN", "()Ljava/util/Locale;", |ctx, _args| {
        let s1 = ctx.create_string("ja"); let s2 = ctx.create_string("JP");
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        ctx.set_field(l, 0, Value::Object(Some(s1))); ctx.set_field(l, 1, Value::Object(Some(s2)));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "CHINA", "()Ljava/util/Locale;", |ctx, _args| {
        let s1 = ctx.create_string("zh"); let s2 = ctx.create_string("CN");
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        ctx.set_field(l, 0, Value::Object(Some(s1))); ctx.set_field(l, 1, Value::Object(Some(s2)));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "CANADA", "()Ljava/util/Locale;", |ctx, _args| {
        let s1 = ctx.create_string("en"); let s2 = ctx.create_string("CA");
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        ctx.set_field(l, 0, Value::Object(Some(s1))); ctx.set_field(l, 1, Value::Object(Some(s2)));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "<init>", "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;)V", |ctx, args| {
        let this = obj_arg(args, 0)?;
        ctx.set_field(this, 0, args[1]);
        ctx.set_field(this, 1, args[2]);
        ctx.set_field(this, 2, args[3]);
        Ok(None)
    });
    registry.register(loc, "getVariant", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 2)))
    });
    registry.register(loc, "getDisplayLanguage", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 0))) // return language code as display name
    });
    registry.register(loc, "getDisplayCountry", "()Ljava/lang/String;", |ctx, args| {
        let this = obj_arg(args, 0)?;
        Ok(Some(ctx.get_field(this, 1)))
    });
    registry.register(loc, "getAvailableLocales", "()[Ljava/util/Locale;", |ctx, _args| {
        let locales_data = [("en", "US"), ("en", "GB"), ("en", ""), ("fr", "FR"), ("de", "DE"),
            ("ja", "JP"), ("zh", "CN"), ("es", "ES"), ("it", "IT"), ("pt", "BR")];
        let arr = ctx.new_ref_array(rustjvm_types::ClassId::new(0), locales_data.len());
        for (i, (lang, country)) in locales_data.iter().enumerate() {
            let s1 = ctx.create_string(lang);
            let s2 = ctx.create_string(country);
            let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
            ctx.set_field(l, 0, Value::Object(Some(s1)));
            ctx.set_field(l, 1, Value::Object(Some(s2)));
            ctx.set_array_element(arr, i, Value::Object(Some(l)));
        }
        Ok(Some(Value::Object(Some(arr))))
    });
    registry.register(loc, "setDefault", "(Ljava/util/Locale;)V", |_ctx, args| {
        if let Some(Value::Object(Some(l))) = args.first() {
            *locale_default().lock() = Some(*l);
        } else {
            *locale_default().lock() = None;
        }
        Ok(None)
    });
    registry.register(loc, "setDefault", "(Ljava/util/Locale$Category;Ljava/util/Locale;)V", |_ctx, args| {
        // Java 7+ overload: ignore the Category and update the global default.
        if let Some(Value::Object(Some(l))) = args.get(1) {
            *locale_default().lock() = Some(*l);
        }
        Ok(None)
    });
    registry.register(loc, "getDefault", "()Ljava/util/Locale;", |ctx, _args| {
        if let Some(stored) = *locale_default().lock() {
            return Ok(Some(Value::Object(Some(stored))));
        }
        // Fallback: en_US
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        let lang = ctx.create_string("en");
        let country = ctx.create_string("US");
        ctx.set_field(l, 0, Value::Object(Some(lang)));
        ctx.set_field(l, 1, Value::Object(Some(country)));
        ctx.set_field(l, 2, Value::Object(None));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(loc, "getDefault", "(Ljava/util/Locale$Category;)Ljava/util/Locale;", |ctx, _args| {
        if let Some(stored) = *locale_default().lock() {
            return Ok(Some(Value::Object(Some(stored))));
        }
        let l = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
        let lang = ctx.create_string("en");
        let country = ctx.create_string("US");
        ctx.set_field(l, 0, Value::Object(Some(lang)));
        ctx.set_field(l, 1, Value::Object(Some(country)));
        ctx.set_field(l, 2, Value::Object(None));
        Ok(Some(Value::Object(Some(l))))
    });
    registry.register(
        loc,
        "forLanguageTag",
        "(Ljava/lang/String;)Ljava/util/Locale;",
        native_locale_for_tag,
    );
}

const LOC_FIELD_LANG: usize = 0;
const LOC_FIELD_COUNTRY: usize = 1;
const LOC_FIELD_VARIANT: usize = 2;

fn locale_alloc(ctx: &mut dyn NativeContext, lang: &str, country: &str) -> ObjectRef {
    let loc = alloc_concurrent_synthetic(ctx, "java/util/Locale", 3);
    let l = ctx.create_string(lang);
    let c = ctx.create_string(country);
    ctx.set_field(loc, LOC_FIELD_LANG, Value::Object(Some(l)));
    ctx.set_field(loc, LOC_FIELD_COUNTRY, Value::Object(Some(c)));
    ctx.set_field(loc, LOC_FIELD_VARIANT, Value::Object(None));
    loc
}

fn native_locale_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    ctx.set_field(
        this,
        LOC_FIELD_LANG,
        args.get(1).copied().unwrap_or(Value::Object(None)),
    );
    ctx.set_field(this, LOC_FIELD_COUNTRY, Value::Object(None));
    ctx.set_field(this, LOC_FIELD_VARIANT, Value::Object(None));
    Ok(None)
}

fn native_locale_init2(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    ctx.set_field(
        this,
        LOC_FIELD_LANG,
        args.get(1).copied().unwrap_or(Value::Object(None)),
    );
    ctx.set_field(
        this,
        LOC_FIELD_COUNTRY,
        args.get(2).copied().unwrap_or(Value::Object(None)),
    );
    ctx.set_field(this, LOC_FIELD_VARIANT, Value::Object(None));
    Ok(None)
}

fn native_locale_get_default(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    let loc = locale_alloc(ctx, "en", "US");
    Ok(Some(Value::Object(Some(loc))))
}

fn native_locale_get_lang(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, LOC_FIELD_LANG)))
}

fn native_locale_get_country(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, LOC_FIELD_COUNTRY)))
}

fn native_locale_to_string(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lang = match ctx.get_field(this, LOC_FIELD_LANG) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let country = match ctx.get_field(this, LOC_FIELD_COUNTRY) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let s = if country.is_empty() {
        lang
    } else {
        format!("{}_{}", lang, country)
    };
    let result = ctx.create_string(&s);
    Ok(Some(Value::Object(Some(result))))
}

fn native_locale_to_tag(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lang = match ctx.get_field(this, LOC_FIELD_LANG) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let country = match ctx.get_field(this, LOC_FIELD_COUNTRY) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let s = if country.is_empty() {
        lang
    } else {
        format!("{}-{}", lang, country)
    };
    let result = ctx.create_string(&s);
    Ok(Some(Value::Object(Some(result))))
}

fn native_locale_equals(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let other = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let a_lang = match ctx.get_field(this, LOC_FIELD_LANG) {
        Value::Object(Some(s)) => ctx.read_string(s),
        _ => None,
    };
    let b_lang = match ctx.get_field(other, LOC_FIELD_LANG) {
        Value::Object(Some(s)) => ctx.read_string(s),
        _ => None,
    };
    let a_country = match ctx.get_field(this, LOC_FIELD_COUNTRY) {
        Value::Object(Some(s)) => ctx.read_string(s),
        _ => None,
    };
    let b_country = match ctx.get_field(other, LOC_FIELD_COUNTRY) {
        Value::Object(Some(s)) => ctx.read_string(s),
        _ => None,
    };
    Ok(Some(Value::Int(
        if a_lang == b_lang && a_country == b_country {
            1
        } else {
            0
        },
    )))
}

fn native_locale_hash_code(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let lang = match ctx.get_field(this, LOC_FIELD_LANG) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let mut h: i32 = 0;
    for b in lang.bytes() {
        h = h.wrapping_mul(31).wrapping_add(b as i32);
    }
    Ok(Some(Value::Int(h)))
}

fn native_locale_english(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(locale_alloc(ctx, "en", "")))))
}
fn native_locale_us(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(locale_alloc(ctx, "en", "US")))))
}
fn native_locale_uk(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(locale_alloc(ctx, "en", "GB")))))
}
fn native_locale_root(ctx: &mut dyn NativeContext, _: &[Value]) -> MethodCallResult {
    Ok(Some(Value::Object(Some(locale_alloc(ctx, "", "")))))
}

fn native_locale_for_tag(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let tag = match args.first() {
        Some(Value::Object(Some(o))) => ctx.read_string(*o).unwrap_or_default(),
        _ => String::new(),
    };
    let parts: Vec<&str> = tag.split('-').collect();
    let lang = parts.first().copied().unwrap_or("");
    let country = parts.get(1).copied().unwrap_or("");
    let loc = locale_alloc(ctx, lang, country);
    Ok(Some(Value::Object(Some(loc))))
}

// ===========================================================================
// Phase 33: java.security — MessageDigest, SecureRandom
// ===========================================================================

fn register_security_natives(registry: &mut NativeMethodRegistry) {
    let md = "java/security/MessageDigest";
    registry.register(
        md,
        "getInstance",
        "(Ljava/lang/String;)Ljava/security/MessageDigest;",
        native_md_get_instance,
    );
    registry.register(md, "update", "([B)V", native_md_update_bytes);
    registry.register(md, "update", "(B)V", native_md_update_byte);
    registry.register(md, "update", "([BII)V", native_md_update_bytes_off);
    registry.register(md, "digest", "()[B", native_md_digest);
    registry.register(md, "digest", "([B)[B", native_md_digest_input);
    registry.register(md, "reset", "()V", native_md_reset);
    registry.register(
        md,
        "getAlgorithm",
        "()Ljava/lang/String;",
        native_md_get_algorithm,
    );
    registry.register(md, "getDigestLength", "()I", native_md_get_digest_length);

    // WP6.7 — `java.util.Random` MUST be deterministic when given a
    // seed (JDK spec).  The previous code aliased the next* methods
    // here to the OS-CSPRNG-backed `native_sr_next_*` helpers, which
    // produced non-deterministic output that broke the seed contract.
    // Both Random and SecureRandom are now registered through the
    // dedicated `securerandom` module, which uses an LCG identical to
    // the JDK's for `Random` and OS entropy for `SecureRandom`.
    crate::securerandom::register_random_and_securerandom_natives(registry);
}

/// T2.3.5: `Random.nextFloat` — returns a float uniformly distributed
/// in [0.0, 1.0). Matches the JDK formula: take the top 24 bits of a
/// seed step and divide by `2^24`.
fn native_random_next_float(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Float(0.0))),
    };
    let seed = sr_next_seed(ctx, this);
    let bits = ((seed >> 16) as u32) >> 8; // top 24 bits
    let f = (bits as f32) / ((1u32 << 24) as f32);
    Ok(Some(Value::Float(f)))
}

/// T2.3.5: `Random.nextGaussian` — returns a double sampled from the
/// standard normal distribution via the Marsaglia polar method, which
/// is what `java.util.Random` uses under the hood. Two uniform samples
/// from [-1, 1) are rejected until their squared norm `s` lies in
/// (0, 1); the two output samples are then `u * sqrt(-2 ln s / s)` and
/// `v * sqrt(-2 ln s / s)`. We generate one and discard the other —
/// the JDK caches the second but our `Random` is stateless-CSPRNG-backed
/// so there's nothing to cache.
fn native_random_next_gaussian(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Double(0.0))),
    };
    // Draw pairs until we get one inside the unit circle. Cap the
    // retry budget so a pathological PRNG cannot hang the VM —
    // the probability of rejection is ~(1 - π/4) per pair, so 64
    // retries gives < 2^-26 failure probability.
    for _ in 0..64 {
        // Two uniform draws in [-1, 1).
        let s1 = sr_next_seed(ctx, this);
        let u = (((s1 >> 16) as u32 as f64) / (u32::MAX as f64)) * 2.0 - 1.0;
        let s2 = sr_next_seed(ctx, this);
        let v = (((s2 >> 16) as u32 as f64) / (u32::MAX as f64)) * 2.0 - 1.0;
        let s = u * u + v * v;
        if s > 0.0 && s < 1.0 {
            let mult = (-2.0 * s.ln() / s).sqrt();
            return Ok(Some(Value::Double(u * mult)));
        }
    }
    // Fallback: return 0.0. With the CSPRNG backing, reaching this
    // point is vanishingly unlikely, but the VM stays responsive.
    Ok(Some(Value::Double(0.0)))
}

// MessageDigest = 2-field synthetic (algorithm=0 String, data=1 byte[] accumulator)
const MD_FIELD_ALGO: usize = 0;
const MD_FIELD_DATA: usize = 1;

fn native_md_get_instance(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let algo = match args.first() {
        Some(Value::Object(Some(o))) => ctx.read_string(*o).unwrap_or_default(),
        _ => String::new(),
    };
    let upper = algo.to_uppercase().replace('-', "");
    if ![
        "MD5", "SHA1", "SHA256", "SHA384", "SHA512",
        "SHA3256", "SHA3384", "SHA3512",
    ]
    .contains(&upper.as_str())
    {
        // Accept anyway for compatibility — unknown algorithms fall
        // back to SHA-256 inside `compute_digest`, matching the JDK
        // behaviour of NoSuchAlgorithmException being surfaced lazily.
    }
    let md = alloc_concurrent_synthetic(ctx, "java/security/MessageDigest", 2);
    let algo_str = ctx.create_string(&algo);
    ctx.set_field(md, MD_FIELD_ALGO, Value::Object(Some(algo_str)));
    let data = ctx.new_array(rustjvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(md, MD_FIELD_DATA, Value::Object(Some(data)));
    Ok(Some(Value::Object(Some(md))))
}

fn md_append_bytes(ctx: &mut dyn NativeContext, this: ObjectRef, bytes: &[u8]) {
    let old_data = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(o)) => o,
        _ => return,
    };
    let old_len = ctx.array_length(old_data);
    let new_len = old_len + bytes.len();
    let new_data = ctx.new_array(rustjvm_types::ArrayElementType::Byte, new_len);
    for i in 0..old_len {
        let v = ctx.get_array_element(old_data, i);
        ctx.set_array_element(new_data, i, v);
    }
    for (i, &b) in bytes.iter().enumerate() {
        ctx.set_array_element(new_data, old_len + i, Value::Int(b as i8 as i32));
    }
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(new_data)));
}

fn native_md_update_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let arr = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let len = ctx.array_length(arr);
    let mut bytes = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(arr, i) {
            bytes.push(b as u8);
        }
    }
    md_append_bytes(ctx, this, &bytes);
    Ok(None)
}

fn native_md_update_byte(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let b = match args.get(1) {
        Some(Value::Int(v)) => *v as u8,
        _ => 0,
    };
    md_append_bytes(ctx, this, &[b]);
    Ok(None)
}

fn native_md_update_bytes_off(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let arr = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let off = match args.get(2) {
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let len = match args.get(3) {
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let mut bytes = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(arr, off + i) {
            bytes.push(b as u8);
        }
    }
    md_append_bytes(ctx, this, &bytes);
    Ok(None)
}

/// Compute a cryptographic digest using the specified algorithm.
///
/// Classical digests (MD5, SHA-1, SHA-2 family) are served by the
/// in-tree constant-time implementations (`real_md5` / `real_sha1` /
/// `real_sha256` / `real_sha384` / `real_sha512`). The SHA-3 family is
/// provided by the RustCrypto `sha3` crate so RustJVM does not have to
/// re-implement the Keccak permutation.
pub(crate) fn compute_digest(algo: &str, data: &[u8]) -> Vec<u8> {
    use sha3::Digest as _;
    let upper = algo.to_uppercase().replace('-', "");
    match upper.as_str() {
        "MD5" => real_md5(data),
        "SHA1" | "SHA" => real_sha1(data),
        "SHA256" => real_sha256(data),
        "SHA384" => real_sha384(data),
        "SHA512" => real_sha512(data),
        "SHA3256" => {
            let mut h = sha3::Sha3_256::new();
            h.update(data);
            h.finalize().to_vec()
        }
        "SHA3384" => {
            let mut h = sha3::Sha3_384::new();
            h.update(data);
            h.finalize().to_vec()
        }
        "SHA3512" => {
            let mut h = sha3::Sha3_512::new();
            h.update(data);
            h.finalize().to_vec()
        }
        _ => real_sha256(data), // default to SHA-256
    }
}

// ===========================================================================
// Real MD5 implementation (RFC 1321)
// ===========================================================================

/// Per-round shift amounts for MD5
const MD5_S: [u32; 64] = [
    7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,
    5,  9, 14, 20, 5,  9, 14, 20, 5,  9, 14, 20, 5,  9, 14, 20,
    4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,
    6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21,
];

/// Pre-computed T[i] = floor(2^32 * abs(sin(i+1))) for MD5
const MD5_K: [u32; 64] = [
    0xd76aa478, 0xe8c7b756, 0x242070db, 0xc1bdceee,
    0xf57c0faf, 0x4787c62a, 0xa8304613, 0xfd469501,
    0x698098d8, 0x8b44f7af, 0xffff5bb1, 0x895cd7be,
    0x6b901122, 0xfd987193, 0xa679438e, 0x49b40821,
    0xf61e2562, 0xc040b340, 0x265e5a51, 0xe9b6c7aa,
    0xd62f105d, 0x02441453, 0xd8a1e681, 0xe7d3fbc8,
    0x21e1cde6, 0xc33707d6, 0xf4d50d87, 0x455a14ed,
    0xa9e3e905, 0xfcefa3f8, 0x676f02d9, 0x8d2a4c8a,
    0xfffa3942, 0x8771f681, 0x6d9d6122, 0xfde5380c,
    0xa4beea44, 0x4bdecfa9, 0xf6bb4b60, 0xbebfbc70,
    0x289b7ec6, 0xeaa127fa, 0xd4ef3085, 0x04881d05,
    0xd9d4d039, 0xe6db99e5, 0x1fa27cf8, 0xc4ac5665,
    0xf4292244, 0x432aff97, 0xab9423a7, 0xfc93a039,
    0x655b59c3, 0x8f0ccc92, 0xffeff47d, 0x85845dd1,
    0x6fa87e4f, 0xfe2ce6e0, 0xa3014314, 0x4e0811a1,
    0xf7537e82, 0xbd3af235, 0x2ad7d2bb, 0xeb86d391,
];

pub(crate) fn real_md5(data: &[u8]) -> Vec<u8> {
    let mut h0: u32 = 0x67452301;
    let mut h1: u32 = 0xefcdab89;
    let mut h2: u32 = 0x98badcfe;
    let mut h3: u32 = 0x10325476;

    // Pre-processing: pad message
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_le_bytes());

    // Process each 512-bit (64-byte) block
    for chunk in msg.chunks_exact(64) {
        let mut m = [0u32; 16];
        for i in 0..16 {
            m[i] = u32::from_le_bytes([
                chunk[4 * i],
                chunk[4 * i + 1],
                chunk[4 * i + 2],
                chunk[4 * i + 3],
            ]);
        }

        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;

        for i in 0..64 {
            let (f, g) = match i {
                0..=15 => ((b & c) | ((!b) & d), i),
                16..=31 => ((d & b) | ((!d) & c), (5 * i + 1) % 16),
                32..=47 => (b ^ c ^ d, (3 * i + 5) % 16),
                _ => (c ^ (b | (!d)), (7 * i) % 16),
            };
            let temp = d;
            d = c;
            c = b;
            b = b.wrapping_add(
                (a.wrapping_add(f).wrapping_add(MD5_K[i]).wrapping_add(m[g]))
                    .rotate_left(MD5_S[i]),
            );
            a = temp;
        }

        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
    }

    let mut result = Vec::with_capacity(16);
    result.extend_from_slice(&h0.to_le_bytes());
    result.extend_from_slice(&h1.to_le_bytes());
    result.extend_from_slice(&h2.to_le_bytes());
    result.extend_from_slice(&h3.to_le_bytes());
    result
}

// ===========================================================================
// Real SHA-1 implementation (FIPS 180-4)
// ===========================================================================

pub(crate) fn real_sha1(data: &[u8]) -> Vec<u8> {
    let mut h0: u32 = 0x67452301;
    let mut h1: u32 = 0xEFCDAB89;
    let mut h2: u32 = 0x98BADCFE;
    let mut h3: u32 = 0x10325476;
    let mut h4: u32 = 0xC3D2E1F0;

    // Pre-processing: pad message
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    // Process each 512-bit (64-byte) block
    for chunk in msg.chunks_exact(64) {
        let mut w = [0u32; 80];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                chunk[4 * i],
                chunk[4 * i + 1],
                chunk[4 * i + 2],
                chunk[4 * i + 3],
            ]);
        }
        for i in 16..80 {
            w[i] = (w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16]).rotate_left(1);
        }

        let mut a = h0;
        let mut b = h1;
        let mut c = h2;
        let mut d = h3;
        let mut e = h4;

        for i in 0..80 {
            let (f, k) = match i {
                0..=19 => ((b & c) | ((!b) & d), 0x5A827999u32),
                20..=39 => (b ^ c ^ d, 0x6ED9EBA1u32),
                40..=59 => ((b & c) | (b & d) | (c & d), 0x8F1BBCDCu32),
                _ => (b ^ c ^ d, 0xCA62C1D6u32),
            };
            let temp = a
                .rotate_left(5)
                .wrapping_add(f)
                .wrapping_add(e)
                .wrapping_add(k)
                .wrapping_add(w[i]);
            e = d;
            d = c;
            c = b.rotate_left(30);
            b = a;
            a = temp;
        }

        h0 = h0.wrapping_add(a);
        h1 = h1.wrapping_add(b);
        h2 = h2.wrapping_add(c);
        h3 = h3.wrapping_add(d);
        h4 = h4.wrapping_add(e);
    }

    let mut result = Vec::with_capacity(20);
    result.extend_from_slice(&h0.to_be_bytes());
    result.extend_from_slice(&h1.to_be_bytes());
    result.extend_from_slice(&h2.to_be_bytes());
    result.extend_from_slice(&h3.to_be_bytes());
    result.extend_from_slice(&h4.to_be_bytes());
    result
}

// ===========================================================================
// Real SHA-256 implementation (FIPS 180-4)
// ===========================================================================

/// SHA-256 round constants: first 32 bits of the fractional parts of the
/// cube roots of the first 64 primes (2..311).
const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
    0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
    0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
    0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
    0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
    0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
    0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
    0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
    0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

pub(crate) fn real_sha256(data: &[u8]) -> Vec<u8> {
    let mut h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];

    // Pre-processing: pad message
    let bit_len = (data.len() as u64).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    // Process each 512-bit (64-byte) block
    for chunk in msg.chunks_exact(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([
                chunk[4 * i],
                chunk[4 * i + 1],
                chunk[4 * i + 2],
                chunk[4 * i + 3],
            ]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA256_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut result = Vec::with_capacity(32);
    for word in &h {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

/// Compute HMAC-SHA-256: HMAC(key, data) = SHA256((key' XOR opad) || SHA256((key' XOR ipad) || data))
/// where key' is the key padded/hashed to 64 bytes, ipad = 0x36, opad = 0x5c
pub(crate) fn hmac_sha256(key: &[u8], data: &[u8]) -> Vec<u8> {
    const BLOCK_SIZE: usize = 64;

    // Step 1: If key > block size, hash it; if shorter, pad with zeros
    let mut key_block = [0u8; BLOCK_SIZE];
    if key.len() > BLOCK_SIZE {
        let hashed = real_sha256(key);
        key_block[..hashed.len()].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    // Step 2: Create inner and outer padded keys
    let mut i_key_pad = [0u8; BLOCK_SIZE];
    let mut o_key_pad = [0u8; BLOCK_SIZE];
    for i in 0..BLOCK_SIZE {
        i_key_pad[i] = key_block[i] ^ 0x36;
        o_key_pad[i] = key_block[i] ^ 0x5c;
    }

    // Step 3: inner hash = SHA256(i_key_pad || data)
    let mut inner_msg = Vec::with_capacity(BLOCK_SIZE + data.len());
    inner_msg.extend_from_slice(&i_key_pad);
    inner_msg.extend_from_slice(data);
    let inner_hash = real_sha256(&inner_msg);

    // Step 4: outer hash = SHA256(o_key_pad || inner_hash)
    let mut outer_msg = Vec::with_capacity(BLOCK_SIZE + 32);
    outer_msg.extend_from_slice(&o_key_pad);
    outer_msg.extend_from_slice(&inner_hash);
    real_sha256(&outer_msg)
}

// ===========================================================================
// Real SHA-512 implementation (FIPS 180-4) — 64-bit words, 80 rounds
// ===========================================================================

/// SHA-512 round constants: first 64 bits of the fractional parts of the
/// cube roots of the first 80 primes (2..409).
const SHA512_K: [u64; 80] = [
    0x428a2f98d728ae22, 0x7137449123ef65cd, 0xb5c0fbcfec4d3b2f, 0xe9b5dba58189dbbc,
    0x3956c25bf348b538, 0x59f111f1b605d019, 0x923f82a4af194f9b, 0xab1c5ed5da6d8118,
    0xd807aa98a3030242, 0x12835b0145706fbe, 0x243185be4ee4b28c, 0x550c7dc3d5ffb4e2,
    0x72be5d74f27b896f, 0x80deb1fe3b1696b1, 0x9bdc06a725c71235, 0xc19bf174cf692694,
    0xe49b69c19ef14ad2, 0xefbe4786384f25e3, 0x0fc19dc68b8cd5b5, 0x240ca1cc77ac9c65,
    0x2de92c6f592b0275, 0x4a7484aa6ea6e483, 0x5cb0a9dcbd41fbd4, 0x76f988da831153b5,
    0x983e5152ee66dfab, 0xa831c66d2db43210, 0xb00327c898fb213f, 0xbf597fc7beef0ee4,
    0xc6e00bf33da88fc2, 0xd5a79147930aa725, 0x06ca6351e003826f, 0x142929670a0e6e70,
    0x27b70a8546d22ffc, 0x2e1b21385c26c926, 0x4d2c6dfc5ac42aed, 0x53380d139d95b3df,
    0x650a73548baf63de, 0x766a0abb3c77b2a8, 0x81c2c92e47edaee6, 0x92722c851482353b,
    0xa2bfe8a14cf10364, 0xa81a664bbc423001, 0xc24b8b70d0f89791, 0xc76c51a30654be30,
    0xd192e819d6ef5218, 0xd69906245565a910, 0xf40e35855771202a, 0x106aa07032bbd1b8,
    0x19a4c116b8d2d0c8, 0x1e376c085141ab53, 0x2748774cdf8eeb99, 0x34b0bcb5e19b48a8,
    0x391c0cb3c5c95a63, 0x4ed8aa4ae3418acb, 0x5b9cca4f7763e373, 0x682e6ff3d6b2b8a3,
    0x748f82ee5defb2fc, 0x78a5636f43172f60, 0x84c87814a1f0ab72, 0x8cc702081a6439ec,
    0x90befffa23631e28, 0xa4506cebde82bde9, 0xbef9a3f7b2c67915, 0xc67178f2e372532b,
    0xca273eceea26619c, 0xd186b8c721c0c207, 0xeada7dd6cde0eb1e, 0xf57d4f7fee6ed178,
    0x06f067aa72176fba, 0x0a637dc5a2c898a6, 0x113f9804bef90dae, 0x1b710b35131c471b,
    0x28db77f523047d84, 0x32caab7b40c72493, 0x3c9ebe0a15c9bebc, 0x431d67c49c100d4c,
    0x4cc5d4becb3e42b6, 0x597f299cfc657e2a, 0x5fcb6fab3ad6faec, 0x6c44198c4a475817,
];

pub(crate) fn real_sha512(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0x6a09e667f3bcc908, 0xbb67ae8584caa73b,
        0x3c6ef372fe94f82b, 0xa54ff53a5f1d36f1,
        0x510e527fade682d1, 0x9b05688c2b3e6c1f,
        0x1f83d9abfb41bd6b, 0x5be0cd19137e2179,
    ];

    // Pre-processing: pad message to 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    // Process each 1024-bit (128-byte) block
    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],     chunk[8 * i + 1], chunk[8 * i + 2], chunk[8 * i + 3],
                chunk[8 * i + 4], chunk[8 * i + 5], chunk[8 * i + 6], chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    let mut result = Vec::with_capacity(64);
    for word in &h {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

/// SHA-384 is SHA-512 with different initial values, truncated to 384 bits (48 bytes).
pub(crate) fn real_sha384(data: &[u8]) -> Vec<u8> {
    let mut h: [u64; 8] = [
        0xcbbb9d5dc1059ed8, 0x629a292a367cd507,
        0x9159015a3070dd17, 0x152fecd8f70e5939,
        0x67332667ffc00b31, 0x8eb44a8768581511,
        0xdb0c2e0d64f98fa7, 0x47b5481dbefa4fa4,
    ];

    // Same padding as SHA-512: 1024-bit blocks
    let bit_len = (data.len() as u128).wrapping_mul(8);
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 128 != 112 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in msg.chunks_exact(128) {
        let mut w = [0u64; 80];
        for i in 0..16 {
            w[i] = u64::from_be_bytes([
                chunk[8 * i],     chunk[8 * i + 1], chunk[8 * i + 2], chunk[8 * i + 3],
                chunk[8 * i + 4], chunk[8 * i + 5], chunk[8 * i + 6], chunk[8 * i + 7],
            ]);
        }
        for i in 16..80 {
            let s0 = w[i - 15].rotate_right(1) ^ w[i - 15].rotate_right(8) ^ (w[i - 15] >> 7);
            let s1 = w[i - 2].rotate_right(19) ^ w[i - 2].rotate_right(61) ^ (w[i - 2] >> 6);
            w[i] = w[i - 16].wrapping_add(s0).wrapping_add(w[i - 7]).wrapping_add(s1);
        }

        let mut a = h[0];
        let mut b = h[1];
        let mut c = h[2];
        let mut d = h[3];
        let mut e = h[4];
        let mut f = h[5];
        let mut g = h[6];
        let mut hh = h[7];

        for i in 0..80 {
            let s1 = e.rotate_right(14) ^ e.rotate_right(18) ^ e.rotate_right(41);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA512_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(28) ^ a.rotate_right(34) ^ a.rotate_right(39);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);

            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(temp1);
            d = c;
            c = b;
            b = a;
            a = temp1.wrapping_add(temp2);
        }

        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }

    // Truncate to 384 bits (6 words = 48 bytes)
    let mut result = Vec::with_capacity(48);
    for word in &h[..6] {
        result.extend_from_slice(&word.to_be_bytes());
    }
    result
}

// ===========================================================================
// Generic HMAC construction (RFC 2104)
// ===========================================================================

/// Generic HMAC: HMAC(K, data) = H((K' ⊕ opad) || H((K' ⊕ ipad) || data))
/// `hash_fn` is the underlying hash, `block_size` is the hash's internal block size.
fn hmac_generic(
    key: &[u8],
    data: &[u8],
    hash_fn: fn(&[u8]) -> Vec<u8>,
    block_size: usize,
) -> Vec<u8> {
    // Step 1: If key > block size, hash it; if shorter, pad with zeros
    let mut key_block = vec![0u8; block_size];
    if key.len() > block_size {
        let hashed = hash_fn(key);
        key_block[..hashed.len()].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }

    // Step 2: Create inner and outer padded keys
    let mut i_key_pad = vec![0u8; block_size];
    let mut o_key_pad = vec![0u8; block_size];
    for i in 0..block_size {
        i_key_pad[i] = key_block[i] ^ 0x36;
        o_key_pad[i] = key_block[i] ^ 0x5c;
    }

    // Step 3: inner hash = H(i_key_pad || data)
    let mut inner_msg = Vec::with_capacity(block_size + data.len());
    inner_msg.extend_from_slice(&i_key_pad);
    inner_msg.extend_from_slice(data);
    let inner_hash = hash_fn(&inner_msg);

    // Step 4: outer hash = H(o_key_pad || inner_hash)
    let mut outer_msg = Vec::with_capacity(block_size + inner_hash.len());
    outer_msg.extend_from_slice(&o_key_pad);
    outer_msg.extend_from_slice(&inner_hash);
    hash_fn(&outer_msg)
}

/// HMAC-SHA-384 (128-byte block size, same as SHA-512)
pub(crate) fn hmac_sha384(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha384, 128)
}

/// HMAC-SHA-512 (128-byte block size)
pub(crate) fn hmac_sha512(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha512, 128)
}

/// HMAC-SHA-1 (64-byte block size)
pub(crate) fn hmac_sha1(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_sha1, 64)
}

/// HMAC-MD5 (64-byte block size)
pub(crate) fn hmac_md5(key: &[u8], data: &[u8]) -> Vec<u8> {
    hmac_generic(key, data, real_md5, 64)
}

fn native_md_digest(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let data_arr = match ctx.get_field(this, MD_FIELD_DATA) {
        Value::Object(Some(o)) => o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let len = ctx.array_length(data_arr);
    let mut data = Vec::with_capacity(len);
    for i in 0..len {
        if let Value::Int(b) = ctx.get_array_element(data_arr, i) {
            data.push(b as u8);
        }
    }
    let digest = compute_digest(&algo, &data);
    let result = ctx.new_array(rustjvm_types::ArrayElementType::Byte, digest.len());
    for (i, &b) in digest.iter().enumerate() {
        ctx.set_array_element(result, i, Value::Int(b as i8 as i32));
    }
    // Reset
    let empty = ctx.new_array(rustjvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(Some(Value::Object(Some(result))))
}

fn native_md_digest_input(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    // update with input first
    if let Some(Value::Object(Some(arr))) = args.get(1) {
        let len = ctx.array_length(*arr);
        let mut bytes = Vec::with_capacity(len);
        for i in 0..len {
            if let Value::Int(b) = ctx.get_array_element(*arr, i) {
                bytes.push(b as u8);
            }
        }
        md_append_bytes(ctx, this, &bytes);
    }
    native_md_digest(ctx, args)
}

fn native_md_reset(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let empty = ctx.new_array(rustjvm_types::ArrayElementType::Byte, 0);
    ctx.set_field(this, MD_FIELD_DATA, Value::Object(Some(empty)));
    Ok(None)
}

fn native_md_get_algorithm(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    Ok(Some(ctx.get_field(this, MD_FIELD_ALGO)))
}

fn native_md_get_digest_length(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let algo = match ctx.get_field(this, MD_FIELD_ALGO) {
        Value::Object(Some(s)) => ctx.read_string(s).unwrap_or_default(),
        _ => String::new(),
    };
    let len = match algo.to_uppercase().replace('-', "").as_str() {
        "MD5" => 16,
        "SHA1" | "SHA" => 20,
        "SHA256" | "SHA3256" => 32,
        "SHA384" | "SHA3384" => 48,
        "SHA512" | "SHA3512" => 64,
        _ => 32,
    };
    Ok(Some(Value::Int(len)))
}

// SecureRandom — uses OS cryptographic entropy (BCryptGenRandom / /dev/urandom)
// for all random generation. The previous splitmix64 PRNG has been removed from
// all SecureRandom paths to prevent predictable output.

/// Fill a buffer with OS cryptographic entropy.
/// Mirrors crypto_impl::os_random_bytes but inlined here to avoid
/// feature-gate dependency on legacy-synthetic-crypto.
fn sr_os_random_bytes(buf: &mut [u8]) -> bool {
    #[cfg(target_os = "windows")]
    {
        #[link(name = "advapi32")]
        extern "system" {
            #[link_name = "SystemFunction036"]
            fn RtlGenRandom(buf: *mut u8, len: u32) -> u8;
        }
        for chunk in buf.chunks_mut(u32::MAX as usize) {
            let ok = unsafe { RtlGenRandom(chunk.as_mut_ptr(), chunk.len() as u32) };
            if ok == 0 {
                return false;
            }
        }
        true
    }
    #[cfg(not(target_os = "windows"))]
    {
        use std::io::Read;
        if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
            return f.read_exact(buf).is_ok();
        }
        false
    }
}

/// Get a cryptographically random u64 from OS entropy.
fn sr_os_random_u64() -> u64 {
    let mut buf = [0u8; 8];
    if !sr_os_random_bytes(&mut buf) {
        // Fallback: system_entropy_seed uses RandomState which itself uses OS entropy
        return system_entropy_seed();
    }
    u64::from_le_bytes(buf)
}

/// Gather entropy from multiple system sources and mix them into a seed.
/// Used only as a last-resort fallback when direct OS entropy fails.
fn system_entropy_seed() -> u64 {
    use std::collections::hash_map::RandomState;
    use std::hash::{BuildHasher, Hasher};
    let s = RandomState::new();
    let mut h = s.build_hasher();
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64;
    h.write_u64(nanos);
    let tid = format!("{:?}", std::thread::current().id());
    h.write(tid.as_bytes());
    let s2 = RandomState::new();
    let h2 = s2.build_hasher();
    h.write_u64(h2.finish());
    h.finish()
}

fn native_secure_random_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let seed = sr_os_random_u64() as i64;
    ctx.set_field(this, 0, Value::Long(seed));
    ctx.set_field(this, 1, Value::Int(0));
    Ok(None)
}

fn sr_next_seed(ctx: &mut dyn NativeContext, this: ObjectRef) -> i64 {
    // Use OS entropy directly for each call (CSPRNG).
    // The object's seed field is updated for compatibility but the output
    // comes from the OS, not from a deterministic PRNG.
    let val = sr_os_random_u64();
    ctx.set_field(this, 0, Value::Long(val as i64));
    val as i64
}

fn native_sr_next_int(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int((seed >> 16) as i32)))
}

fn native_sr_next_int_bound(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let bound = match args.get(1) {
        Some(Value::Int(v)) => *v,
        _ => 1,
    };
    if bound <= 0 {
        return Ok(Some(Value::Int(0)));
    }
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int(
        ((seed >> 16) as i32).unsigned_abs() as i32 % bound,
    )))
}

fn native_sr_next_long(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Long(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Long(seed)))
}

fn native_sr_next_bytes(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let _this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let arr = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let len = ctx.array_length(arr);
    if len == 0 {
        return Ok(None);
    }
    // Fill the buffer in a single bulk call to the OS CSPRNG instead of
    // burning a 64-bit random draw per byte (which discarded 7/8 of each
    // call's entropy). If the CSPRNG is unavailable we fall back to
    // per-byte `sr_os_random_u64` mixing so we never silently produce
    // deterministic bytes.
    let mut buf = vec![0u8; len];
    if !sr_os_random_bytes(&mut buf) {
        for chunk in buf.chunks_mut(8) {
            let v = sr_os_random_u64().to_le_bytes();
            for (dst, src) in chunk.iter_mut().zip(v.iter()) {
                *dst = *src;
            }
        }
    }
    for (i, &b) in buf.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Int((b as i8) as i32));
    }
    // Zero the intermediate buffer — cheap defence in depth even though
    // the heap copy in `set_array_element` is already the authoritative
    // destination.
    for b in buf.iter_mut() {
        *b = 0;
    }
    Ok(None)
}

fn native_sr_next_double(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Double(0.0))),
    };
    let seed = sr_next_seed(ctx, this);
    let d = ((seed >> 16) as u32 as f64) / (u32::MAX as f64);
    Ok(Some(Value::Double(d)))
}

fn native_sr_next_boolean(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let seed = sr_next_seed(ctx, this);
    Ok(Some(Value::Int(if seed & 1 == 0 { 0 } else { 1 })))
}

fn native_sr_generate_seed(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let num_bytes = match args.get(1) {
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let arr = ctx.new_array(rustjvm_types::ArrayElementType::Byte, num_bytes);
    // Use OS entropy directly (CSPRNG) for seed generation.
    let mut buf = vec![0u8; num_bytes];
    if !sr_os_random_bytes(&mut buf) {
        // Fallback: use system_entropy_seed per-byte
        for (i, b) in buf.iter_mut().enumerate() {
            *b = (system_entropy_seed() >> (i % 8 * 8)) as u8;
        }
    }
    for (i, &b) in buf.iter().enumerate() {
        ctx.set_array_element(arr, i, Value::Int(b as i8 as i32));
    }
    Ok(Some(Value::Object(Some(arr))))
}

// ===========================================================================
// Phase 34: ReadWriteLock, Atomic extras, LongAdder
// ===========================================================================

fn register_rwlock_natives(registry: &mut NativeMethodRegistry) {
    let rwl = "java/util/concurrent/locks/ReentrantReadWriteLock";
    let rl = "java/util/concurrent/locks/ReentrantReadWriteLock$ReadLock";
    let wl = "java/util/concurrent/locks/ReentrantReadWriteLock$WriteLock";

    // ReentrantReadWriteLock = 3-field synthetic (readers=0, writer=1, fair=2)
    registry.register(rwl, "<init>", "()V", native_rwl_init);
    registry.register(rwl, "<init>", "(Z)V", native_rwl_init_fair);
    registry.register(
        rwl,
        "readLock",
        "()Ljava/util/concurrent/locks/ReentrantReadWriteLock$ReadLock;",
        native_rwl_read_lock,
    );
    registry.register(
        rwl,
        "writeLock",
        "()Ljava/util/concurrent/locks/ReentrantReadWriteLock$WriteLock;",
        native_rwl_write_lock,
    );

    // ReadLock = 1-field synthetic (parent=0 → ReentrantReadWriteLock).
    //
    // WP4.7: The lock/unlock/tryLock callbacks now delegate to the
    // process-wide RwLock backend in `crate::stamped_lock` instead of
    // toggling a per-object field. The old field-toggle was effectively
    // unsynchronized (two threads racing on `lock()` would each read
    // readers=0, both bump it to 1, neither would exclude a writer).
    // Real exclusion is now via a Mutex+Condvar slot keyed on the parent
    // RWL's address.
    fn rwl_parent_addr(ctx: &mut dyn NativeContext, this: ObjectRef) -> Option<usize> {
        match ctx.get_field(this, 0) {
            Value::Object(Some(parent)) => Some(parent.as_ptr() as usize),
            _ => None,
        }
    }

    registry.register(rl, "lock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_read_lock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(rl, "unlock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_read_unlock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(rl, "tryLock", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_read_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(rl, "tryLock", "(JLjava/util/concurrent/TimeUnit;)Z", |ctx, args| {
        // Timed variant — caller already pre-rounded the timeout, and
        // the contention ratio in real apps doesn't justify a pdqueue
        // here. Treat as fast-path tryLock.
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_read_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(rl, "lockInterruptibly", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_read_lock(addr, ctx.thread_id());
        }
        Ok(None)
    });

    // WriteLock = 1-field synthetic (parent=0). WP4.7: delegate to the
    // process-wide RwLock backend (see comment on the read lock above).
    registry.register(wl, "lock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_write_lock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(wl, "unlock", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_write_unlock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(wl, "tryLock", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_write_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(wl, "tryLock", "(JLjava/util/concurrent/TimeUnit;)Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let ok = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_try_write_lock(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(ok))))
    });
    registry.register(wl, "lockInterruptibly", "()V", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        if let Some(addr) = rwl_parent_addr(ctx, this) {
            crate::stamped_lock::rw_write_lock(addr, ctx.thread_id());
        }
        Ok(None)
    });
    registry.register(wl, "isHeldByCurrentThread", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let held = match rwl_parent_addr(ctx, this) {
            Some(a) => crate::stamped_lock::rw_write_is_held(a, ctx.thread_id()),
            None => false,
        };
        Ok(Some(Value::Int(i32::from(held))))
    });

    // StampedLock — real optimistic read / exclusive write lock with stamp validation.
    // Uses a global state map keyed by object address for per-lock state.
    let sl = "java/util/concurrent/locks/StampedLock";
    registry.register(sl, "<init>", "()V", native_stamped_init);
    registry.register(sl, "readLock", "()J", native_stamped_read_lock);
    registry.register(sl, "writeLock", "()J", native_stamped_write_lock);
    registry.register(sl, "tryOptimisticRead", "()J", native_stamped_optimistic);
    registry.register(sl, "unlockRead", "(J)V", native_stamped_unlock_read);
    registry.register(sl, "unlockWrite", "(J)V", native_stamped_unlock_write);
    registry.register(sl, "validate", "(J)Z", native_stamped_validate);
    registry.register(sl, "tryReadLock", "()J", native_stamped_try_read_lock);
    registry.register(sl, "tryWriteLock", "()J", native_stamped_try_write_lock);
    registry.register(sl, "tryConvertToWriteLock", "(J)J", native_stamped_try_convert_to_write);
    registry.register(sl, "tryConvertToReadLock", "(J)J", native_stamped_try_convert_to_read);
    registry.register(sl, "isWriteLocked", "()Z", native_stamped_is_write_locked);
    registry.register(sl, "isReadLocked", "()Z", native_stamped_is_read_locked);
    registry.register(sl, "getReadLockCount", "()I", native_stamped_get_read_lock_count);
}

fn native_rwl_init(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    ctx.set_field(this, 0, Value::Int(0)); // readers
    ctx.set_field(this, 1, Value::Int(0)); // writer
    ctx.set_field(this, 2, Value::Int(0)); // fair
    Ok(None)
}

fn native_rwl_init_fair(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(None),
    };
    let fair = match args.get(1) {
        Some(Value::Int(v)) => *v,
        _ => 0,
    };
    ctx.set_field(this, 0, Value::Int(0));
    ctx.set_field(this, 1, Value::Int(0));
    ctx.set_field(this, 2, Value::Int(fair));
    Ok(None)
}

fn native_rwl_read_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lock = alloc_concurrent_synthetic(
        ctx,
        "java/util/concurrent/locks/ReentrantReadWriteLock$ReadLock",
        1,
    );
    ctx.set_field(lock, 0, Value::Object(Some(this)));
    Ok(Some(Value::Object(Some(lock))))
}

fn native_rwl_write_lock(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let lock = alloc_concurrent_synthetic(
        ctx,
        "java/util/concurrent/locks/ReentrantReadWriteLock$WriteLock",
        1,
    );
    ctx.set_field(lock, 0, Value::Object(Some(this)));
    Ok(Some(Value::Object(Some(lock))))
}

// ---------------------------------------------------------------------------
// StampedLock — real implementation backed by `stamped_lock` module.
// ---------------------------------------------------------------------------
//
// WP4.7: The earlier version of this code did `monitor_enter; monitor_wait(5);
// monitor_exit` between observing the state and parking, so a notification
// arriving in that gap was lost — writers blocked for the full 5 ms even
// when contention had already cleared. The fix is to hold a real
// `parking_lot::Mutex` across the check-and-park so `Condvar::wait`
// releases it atomically. All of that lives in `crate::stamped_lock` so
// it can be unit-tested independently of the NativeContext plumbing.
//
// State encoding (see `stamped_lock` module for the full rationale):
//   stamp: i64   — even = no writer, odd = writer active. Starts at 256.
//   readers: i32 — number of active read locks.

const STAMPED_ORIGIN: i64 = crate::stamped_lock::STAMPED_ORIGIN;

fn stamped_addr(args: &[Value]) -> Option<usize> {
    match args.first() {
        Some(Value::Object(Some(o))) => Some(o.as_ptr() as usize),
        _ => None,
    }
}

fn native_stamped_init(_ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    if let Some(addr) = stamped_addr(args) {
        crate::stamped_lock::stamped_init(addr);
    }
    Ok(None)
}

fn native_stamped_write_lock(_ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let addr = match stamped_addr(args) {
        Some(a) => a,
        None => return Ok(Some(Value::Long(0))),
    };
    Ok(Some(Value::Long(crate::stamped_lock::stamped_write_lock(addr))))
}

