// ===========================================================================
// Phase 35: Missing functional interfaces
// ===========================================================================

fn register_functional_extras_natives(registry: &mut NativeMethodRegistry) {
    // BiFunction, BiConsumer, BiPredicate — these are SAM interfaces used via lambdas
    // We register identity/composition methods
    let bf = "java/util/function/BiFunction";
    registry.register(
        bf,
        "andThen",
        "(Ljava/util/function/Function;)Ljava/util/function/BiFunction;",
        native_noop_return_this,
    );

    let bc = "java/util/function/BiConsumer";
    registry.register(
        bc,
        "andThen",
        "(Ljava/util/function/BiConsumer;)Ljava/util/function/BiConsumer;",
        native_noop_return_this,
    );

    // UnaryOperator.identity()
    let uo = "java/util/function/UnaryOperator";
    registry.register(
        uo,
        "identity",
        "()Ljava/util/function/UnaryOperator;",
        native_identity_function,
    );

    // Function.identity()
    let func = "java/util/function/Function";
    registry.register(
        func,
        "identity",
        "()Ljava/util/function/Function;",
        native_identity_function,
    );

    // Predicate.not, isEqual
    let pred = "java/util/function/Predicate";
    registry.register(
        pred,
        "isEqual",
        "(Ljava/lang/Object;)Ljava/util/function/Predicate;",
        native_noop_return_this,
    );
}

fn native_noop_return_this(_ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    Ok(args.first().copied())
}

fn native_identity_function(ctx: &mut dyn NativeContext, _args: &[Value]) -> MethodCallResult {
    // Return a proxy that returns its argument (identity)
    // Simplified: return null (callers will handle null identity specially)
    let _ = ctx;
    Ok(Some(Value::Object(None)))
}

// ===========================================================================
// Phase 37: Enterprise — ProcessBuilder, StackTraceElement, ServiceLoader, System.getenv
// ===========================================================================

fn register_enterprise_natives(registry: &mut NativeMethodRegistry) {
    // StackTraceElement = 4-field (declaringClass, methodName, fileName, lineNumber)
    let ste = "java/lang/StackTraceElement";
    registry.register(
        ste,
        "<init>",
        "(Ljava/lang/String;Ljava/lang/String;Ljava/lang/String;I)V",
        native_ste_init,
    );
    registry.register(
        ste,
        "getClassName",
        "()Ljava/lang/String;",
        native_ste_get_class,
    );
    registry.register(
        ste,
        "getMethodName",
        "()Ljava/lang/String;",
        native_ste_get_method,
    );
    registry.register(
        ste,
        "getFileName",
        "()Ljava/lang/String;",
        native_ste_get_file,
    );
    registry.register(ste, "getLineNumber", "()I", native_ste_get_line);
    registry.register(
        ste,
        "toString",
        "()Ljava/lang/String;",
        native_ste_to_string,
    );
    registry.register(ste, "isNativeMethod", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });

    // ProcessBuilder + Process (simplified)
    let pb = "java/lang/ProcessBuilder";
    registry.register(pb, "<init>", "(Ljava/util/List;)V", native_pb_init);
    registry.register(pb, "<init>", "([Ljava/lang/String;)V", native_pb_init);
    registry.register(pb, "command", "()Ljava/util/List;", native_pb_command);
    registry.register(pb, "start", "()Ljava/lang/Process;", native_pb_start);

    let proc = "java/lang/Process";
    registry.register(proc, "waitFor", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    registry.register(proc, "exitValue", "()I", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    registry.register(proc, "isAlive", "()Z", |_ctx, _args| {
        Ok(Some(Value::Int(0)))
    });
    registry.register(proc, "destroy", "()V", |ctx, args| {
        // Process is 3-field synthetic (exit_code=0, stdout=1, stderr=2). Our spawn model
        // captures stdout/stderr synchronously via Command::output(), so destroy() merely
        // needs to mark the process as terminated. SIGTERM exit code = 143.
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(None),
        };
        ctx.set_field(this, 0, Value::Int(143));
        Ok(None)
    });
    registry.register(
        proc,
        "destroyForcibly",
        "()Ljava/lang/Process;",
        native_noop_return_this,
    );

    // Thread enhancements
    registry.register(
        "java/lang/Thread",
        "getStackTrace",
        "()[Ljava/lang/StackTraceElement;",
        native_thread_get_stack_trace,
    );
}

