fn native_charseq_length(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let s = ctx.read_string(this).unwrap_or_default();
    Ok(Some(Value::Int(s.encode_utf16().count() as i32)))
}

fn native_charseq_char_at(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let this = match args.first() {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Int(0))),
    };
    let idx = match args.get(1) {
        Some(Value::Int(v)) => *v as usize,
        _ => 0,
    };
    let s = ctx.read_string(this).unwrap_or_default();
    let chars: Vec<u16> = s.encode_utf16().collect();
    Ok(Some(
        Value::Int(chars.get(idx).copied().unwrap_or(0) as i32),
    ))
}

