// ===========================================================================
// Phase 46: Functional Interfaces Completion — primitive specialized
// ===========================================================================

fn register_functional_completion_natives(registry: &mut NativeMethodRegistry) {
    // SAM interfaces — these are just markers for lambda dispatch; the actual invocation
    // goes through invoke_virtual on the lambda proxy. We register default/static methods.

    // IntPredicate
    let ip = "java/util/function/IntPredicate";
    registry.register(
        ip,
        "and",
        "(Ljava/util/function/IntPredicate;)Ljava/util/function/IntPredicate;",
        native_return_self,
    );
    registry.register(
        ip,
        "or",
        "(Ljava/util/function/IntPredicate;)Ljava/util/function/IntPredicate;",
        native_return_self,
    );
    registry.register(
        ip,
        "negate",
        "()Ljava/util/function/IntPredicate;",
        native_return_self,
    );

    // LongPredicate
    let lp = "java/util/function/LongPredicate";
    registry.register(
        lp,
        "and",
        "(Ljava/util/function/LongPredicate;)Ljava/util/function/LongPredicate;",
        native_return_self,
    );
    registry.register(
        lp,
        "or",
        "(Ljava/util/function/LongPredicate;)Ljava/util/function/LongPredicate;",
        native_return_self,
    );
    registry.register(
        lp,
        "negate",
        "()Ljava/util/function/LongPredicate;",
        native_return_self,
    );

    // DoublePredicate
    let dp = "java/util/function/DoublePredicate";
    registry.register(
        dp,
        "and",
        "(Ljava/util/function/DoublePredicate;)Ljava/util/function/DoublePredicate;",
        native_return_self,
    );
    registry.register(
        dp,
        "or",
        "(Ljava/util/function/DoublePredicate;)Ljava/util/function/DoublePredicate;",
        native_return_self,
    );
    registry.register(
        dp,
        "negate",
        "()Ljava/util/function/DoublePredicate;",
        native_return_self,
    );

    // BiPredicate
    let bp = "java/util/function/BiPredicate";
    registry.register(
        bp,
        "and",
        "(Ljava/util/function/BiPredicate;)Ljava/util/function/BiPredicate;",
        native_return_self,
    );
    registry.register(
        bp,
        "or",
        "(Ljava/util/function/BiPredicate;)Ljava/util/function/BiPredicate;",
        native_return_self,
    );
    registry.register(
        bp,
        "negate",
        "()Ljava/util/function/BiPredicate;",
        native_return_self,
    );

    // IntUnaryOperator
    let iuo = "java/util/function/IntUnaryOperator";
    registry.register(
        iuo,
        "identity",
        "()Ljava/util/function/IntUnaryOperator;",
        native_return_null,
    );
    registry.register(
        iuo,
        "compose",
        "(Ljava/util/function/IntUnaryOperator;)Ljava/util/function/IntUnaryOperator;",
        native_return_self,
    );
    registry.register(
        iuo,
        "andThen",
        "(Ljava/util/function/IntUnaryOperator;)Ljava/util/function/IntUnaryOperator;",
        native_return_self,
    );

    // LongUnaryOperator
    let luo = "java/util/function/LongUnaryOperator";
    registry.register(
        luo,
        "identity",
        "()Ljava/util/function/LongUnaryOperator;",
        native_return_null,
    );
    registry.register(
        luo,
        "compose",
        "(Ljava/util/function/LongUnaryOperator;)Ljava/util/function/LongUnaryOperator;",
        native_return_self,
    );
    registry.register(
        luo,
        "andThen",
        "(Ljava/util/function/LongUnaryOperator;)Ljava/util/function/LongUnaryOperator;",
        native_return_self,
    );

    // DoubleUnaryOperator
    let duo = "java/util/function/DoubleUnaryOperator";
    registry.register(
        duo,
        "identity",
        "()Ljava/util/function/DoubleUnaryOperator;",
        native_return_null,
    );
    registry.register(
        duo,
        "compose",
        "(Ljava/util/function/DoubleUnaryOperator;)Ljava/util/function/DoubleUnaryOperator;",
        native_return_self,
    );
    registry.register(
        duo,
        "andThen",
        "(Ljava/util/function/DoubleUnaryOperator;)Ljava/util/function/DoubleUnaryOperator;",
        native_return_self,
    );

    // Predicate (enhance existing)
    let pred = "java/util/function/Predicate";
    registry.register(
        pred,
        "not",
        "(Ljava/util/function/Predicate;)Ljava/util/function/Predicate;",
        native_return_first_arg,
    );

    // IntSummaryStatistics
    let iss = "java/util/IntSummaryStatistics";
    registry.register(iss, "<init>", "()V", native_iss_init);
    registry.register(iss, "accept", "(I)V", native_iss_accept);
    registry.register(iss, "getCount", "()J", native_iss_get_count);
    registry.register(iss, "getSum", "()J", native_iss_get_sum);
    registry.register(iss, "getMin", "()I", native_iss_get_min);
    registry.register(iss, "getMax", "()I", native_iss_get_max);
    registry.register(iss, "getAverage", "()D", native_iss_get_average);
    registry.register(
        iss,
        "toString",
        "()Ljava/lang/String;",
        native_iss_to_string,
    );
}

