fn array_new_instance_component_name(
    ctx: &mut dyn NativeContext,
    mirror_arg: Option<&Value>,
) -> String {
    match mirror_arg {
        Some(Value::Object(Some(mirror))) => ctx
            .read_string(*mirror)
            .or_else(|| match ctx.get_field(*mirror, 1) {
                Value::Object(Some(name_obj)) => ctx.read_string(name_obj),
                _ => None,
            })
            .map(|s| s.replace('.', "/"))
            .unwrap_or_else(|| "java/lang/Object".to_string()),
        _ => "java/lang/Object".to_string(),
    }
}

fn array_new_instance_for_component(
    ctx: &mut dyn NativeContext,
    comp_name: &str,
    length: usize,
) -> rustjvm_types::ObjectRef {
    use rustjvm_types::ArrayElementType;
    match comp_name {
        "int" | "I" => ctx.new_array(ArrayElementType::Int, length),
        "long" | "J" => ctx.new_array(ArrayElementType::Long, length),
        "float" | "F" => ctx.new_array(ArrayElementType::Float, length),
        "double" | "D" => ctx.new_array(ArrayElementType::Double, length),
        "boolean" | "Z" => ctx.new_array(ArrayElementType::Boolean, length),
        "byte" | "B" => ctx.new_array(ArrayElementType::Byte, length),
        "char" | "C" => ctx.new_array(ArrayElementType::Char, length),
        "short" | "S" => ctx.new_array(ArrayElementType::Short, length),
        _ => {
            let comp_id = ctx
                .ensure_class_initialized(comp_name)
                .unwrap_or(rustjvm_types::ClassId::new(0));
            ctx.new_ref_array(comp_id, length)
        }
    }
}

fn native_array_new_instance(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let len = match args.get(1) {
        Some(Value::Int(v)) => (*v).max(0) as usize,
        _ => 0,
    };
    let comp_name = array_new_instance_component_name(ctx, args.first());
    let arr = array_new_instance_for_component(ctx, &comp_name, len);
    Ok(Some(Value::Object(Some(arr))))
}

fn native_array_new_instance_multi(
    ctx: &mut dyn NativeContext,
    args: &[Value],
) -> MethodCallResult {
    let dims = match args.get(1) {
        Some(Value::Object(Some(o))) => *o,
        _ => return Ok(Some(Value::Object(None))),
    };
    let len = match ctx.get_array_element(dims, 0) {
        Value::Int(v) => v.max(0) as usize,
        _ => 0,
    };
    let comp_name = array_new_instance_component_name(ctx, args.first());
    let arr = array_new_instance_for_component(ctx, &comp_name, len);
    Ok(Some(Value::Object(Some(arr))))
}

// ===========================================================================
// Phase 47: java.lang.reflect.Proxy — dynamic proxy stubs
// ===========================================================================
//
// WP2.5 (Strategy B+): every proxy still lands on the single synthetic
// class `java/lang/reflect/Proxy$Instance`, but per-proxy data
// (interfaces array, handler) is now stored in dedicated slots and the
// natives expose helpers so reflection round-trips work.
//
// The globals below back `Class.getInterfaces()` on the proxy class
// mirror — see the doc-comment on `vm::runtime::proxy::last_interfaces`
// for the rationale and the known multi-threaded-creation limitation.

/// Most recently created proxy's interfaces array (raw `ObjectRef::as_u64`).
/// `0` = no proxy ever created. Read by `lang_class::native_class_get_interfaces`
/// when the receiver class mirror names `Proxy$Instance`.
static PROXY_LAST_INTERFACES_BITS: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Total proxies created in this process. Diagnostic only.
static PROXY_INSTANCES_CREATED: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

/// Public accessor for `lang_class::native_class_get_interfaces` to
/// pick up the interfaces array of the most recently created proxy.
/// Also public so WP2.5 tests can sanity-check the symbol exists.
pub fn proxy_last_interfaces_bits() -> u64 {
    PROXY_LAST_INTERFACES_BITS.load(std::sync::atomic::Ordering::Acquire)
}

/// Total proxies created in this process — for diagnostics.
pub fn proxy_instances_created() -> u64 {
    PROXY_INSTANCES_CREATED.load(std::sync::atomic::Ordering::Acquire)
}

/// Register the four `java.lang.reflect.Proxy` natives. Public so the
/// real-JDK path in `vm/src/vm/vm_init.rs` and the WP2.5 conformance
/// tests can both reach it. The natives are also called from
/// `register_synthetic_overrides` in synthetic-jdk mode.
pub fn register_reflect_proxy_natives(registry: &mut NativeMethodRegistry) {
    let p = "java/lang/reflect/Proxy";
    registry.register(
        p,
        "isProxyClass",
        "(Ljava/lang/Class;)Z",
        native_proxy_is_proxy_class,
    );
    registry.register(
        p,
        "getInvocationHandler",
        "(Ljava/lang/Object;)Ljava/lang/reflect/InvocationHandler;",
        native_proxy_get_handler,
    );
    registry.register(p, "newProxyInstance",
        "(Ljava/lang/ClassLoader;[Ljava/lang/Class;Ljava/lang/reflect/InvocationHandler;)Ljava/lang/Object;",
        native_proxy_new_instance);
    // WP2.5: helper for the proxy-instance class so callers can read
    // the interfaces back from the proxy itself rather than walking
    // the side-table. Registered on the synthetic class name.
    registry.register(
        "java/lang/reflect/Proxy$Instance",
        "getProxyInterfacesNative",
        "()[Ljava/lang/Class;",
        native_proxy_get_interfaces,
    );
}

fn native_proxy_is_proxy_class(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // Return true if the Class object's name is "java/lang/reflect/Proxy$Instance".
    //
    // Class mirror layout: field 0 = class_id (Int), field 1 = name (String).
    // We accept both the synthetic class name *and* any class id whose
    // resolved name names the proxy class (in case the mirror was
    // assembled by a different code path that left the name field
    // empty).
    let is_proxy = match args.first() {
        Some(Value::Object(Some(class_mirror))) => {
            // Primary path: explicit name field.
            let by_name = match ctx.get_field(*class_mirror, 1) {
                Value::Object(Some(name_ref)) => ctx
                    .read_string(name_ref)
                    .map(|n| n == "java/lang/reflect/Proxy$Instance")
                    .unwrap_or(false),
                _ => false,
            };
            if by_name {
                true
            } else {
                // Secondary path: resolve through class_id.
                match ctx.get_field(*class_mirror, 0) {
                    Value::Int(cid_raw) if cid_raw >= 0 => {
                        let cid = rustjvm_types::ClassId::new(cid_raw as u32);
                        ctx.class_name_of_id(cid)
                            .map(|n| n == "java/lang/reflect/Proxy$Instance")
                            .unwrap_or(false)
                    }
                    _ => false,
                }
            }
        }
        _ => false,
    };
    Ok(Some(Value::Int(if is_proxy { 1 } else { 0 })))
}

fn native_proxy_get_handler(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // Return the InvocationHandler stored in field 0 of the proxy object.
    let handler = match args.first() {
        Some(Value::Object(Some(proxy))) => ctx.get_field(*proxy, 0),
        _ => Value::Object(None),
    };
    Ok(Some(handler))
}

fn native_proxy_new_instance(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    // WP2.5 — track the interfaces array on the proxy so that
    // `proxy.getClass().getInterfaces()` round-trips and so that the
    // dispatch path can see exactly what interfaces the user requested.
    //
    // Args: [classloader, Class[] interfaces, InvocationHandler handler]
    //
    // Field layout (see vm::runtime::proxy):
    //   0 -> InvocationHandler
    //   1 -> Class[] interfaces
    //   2 -> identity-hashcode override (reserved, default 0)
    let interfaces = args.get(1).cloned().unwrap_or(Value::Object(None));
    let handler = args.get(2).cloned().unwrap_or(Value::Object(None));
    let proxy = alloc_concurrent_synthetic(ctx, "java/lang/reflect/Proxy$Instance", 3);
    ctx.set_field(proxy, 0, handler);
    ctx.set_field(proxy, 1, interfaces);
    ctx.set_field(proxy, 2, Value::Int(0));

    // WP2.5: register the most recently created proxy's interfaces
    // array so `Class.getInterfaces()` on the shared Proxy$Instance
    // class mirror can reflect them. See module-level comment for the
    // last-wins limitation.
    if let Value::Object(Some(arr)) = interfaces {
        PROXY_LAST_INTERFACES_BITS.store(arr.as_ptr() as u64, std::sync::atomic::Ordering::Release);
    }
    PROXY_INSTANCES_CREATED.fetch_add(1, std::sync::atomic::Ordering::AcqRel);

    Ok(Some(Value::Object(Some(proxy))))
}

/// Helper for the `proxy.getClass().getInterfaces()` round-trip:
/// fetch the interfaces array stored on the proxy at field 1.
fn native_proxy_get_interfaces(ctx: &mut dyn NativeContext, args: &[Value]) -> MethodCallResult {
    let arr = match args.first() {
        Some(Value::Object(Some(proxy))) => ctx.get_field(*proxy, 1),
        _ => Value::Object(None),
    };
    Ok(Some(arr))
}

// ===========================================================================
// Phases 49-50: Enterprise Final — AtomicBoolean, Modifier extras, Class extras,
// CompletableFuture, Executors, Formatter
// ===========================================================================

fn register_enterprise_final_natives(registry: &mut NativeMethodRegistry) {
    // --- AtomicBoolean (1-field synthetic: value=0 Int) ---
    register_atomic_boolean_natives(registry);

    // --- AtomicStampedReference (2-field: ref=0, stamp=1) ---
    register_atomic_stamped_ref_natives(registry);

    // --- AtomicMarkableReference (2-field: ref=0, mark=1) ---
    register_atomic_markable_ref_natives(registry);

    // --- Modifier extras (remaining bit checks) ---
    let m = "java/lang/reflect/Modifier";
    registry.register(m, "isSynchronized", "(I)Z", native_modifier_is_synchronized);
    registry.register(m, "isVolatile", "(I)Z", native_modifier_is_volatile);
    registry.register(m, "isTransient", "(I)Z", native_modifier_is_transient);
    registry.register(m, "isNative", "(I)Z", native_modifier_is_native);
    registry.register(m, "isInterface", "(I)Z", native_modifier_is_interface);
    registry.register(m, "isStrict", "(I)Z", native_modifier_is_strict);
    registry.register(
        m,
        "toString",
        "(I)Ljava/lang/String;",
        native_modifier_to_string,
    );
    registry.register(m, "classModifiers", "()I", native_modifier_class_modifiers);
    registry.register(
        m,
        "interfaceModifiers",
        "()I",
        native_modifier_interface_modifiers,
    );
    registry.register(m, "fieldModifiers", "()I", native_modifier_field_modifiers);
    registry.register(
        m,
        "methodModifiers",
        "()I",
        native_modifier_method_modifiers,
    );
    registry.register(
        m,
        "constructorModifiers",
        "()I",
        native_modifier_constructor_modifiers,
    );

    // --- Class extras (additional methods not already registered) ---
    let c = "java/lang/Class";
    registry.register(
        c,
        "getComponentType",
        "()Ljava/lang/Class;",
        native_class_get_component_type,
    );
    registry.register(
        c,
        "getPackageName",
        "()Ljava/lang/String;",
        native_class_get_package_name,
    );
    // T19_H10_GET_PACKAGE: real `Class.getPackage()` — synthesises a
    // `java.lang.Package` whose `name`, `implementation*`, and
    // `specification*` fields are populated from the class's source jar
    // manifest. Was `native_return_null`, which broke any code that did
    // `Foo.class.getPackage().getImplementationVersion()` on `<clinit>`.
    registry.register(c, "getPackage", "()Ljava/lang/Package;", native_class_get_package);

    // T19_H11 — moved to `register_essential_natives` so the override
    // is active in real-JDK mode (this `register_synthetic_overrides`
    // function is only called under the `synthetic-jdk` feature gate).
    registry.register(c, "isEnum", "()Z", native_class_is_enum);
    registry.register(c, "isRecord", "()Z", native_class_is_record);
    registry.register(c, "isSealed", "()Z", native_class_is_sealed);
    registry.register(c, "isSynthetic", "()Z", native_return_false);
    registry.register(c, "isAnonymousClass", "()Z", native_return_false);
    registry.register(c, "isLocalClass", "()Z", native_return_false);
    registry.register(c, "isMemberClass", "()Z", native_return_false);
    // NEW-8: Class.isHidden real impl — was native_return_false which
    // shadowed the registration at lib.rs:~325. Both now consult the
    // class's hidden flag through NativeContext::is_class_hidden.
    registry.register(c, "isHidden", "()Z", |ctx, args| {
        let this = match args.first() {
            Some(Value::Object(Some(o))) => *o,
            _ => return Ok(Some(Value::Int(0))),
        };
        let hidden = match lang_class::mirror_class_id(ctx, this) {
            Some(cid) => ctx.is_class_hidden(cid),
            None => false,
        };
        Ok(Some(Value::Int(if hidden { 1 } else { 0 })))
    });
    registry.register(
        c,
        "getCanonicalName",
        "()Ljava/lang/String;",
        native_class_get_canonical_name,
    );
    registry.register(
        c,
        "getTypeName",
        "()Ljava/lang/String;",
        native_class_get_type_name,
    );
    registry.register(
        c,
        "getEnclosingClass",
        "()Ljava/lang/Class;",
        native_return_null,
    );
    registry.register(
        c,
        "getEnclosingMethod",
        "()Ljava/lang/reflect/Method;",
        native_return_null,
    );
    registry.register(
        c,
        "getEnclosingConstructor",
        "()Ljava/lang/reflect/Constructor;",
        native_return_null,
    );
    registry.register(
        c,
        "getDeclaringClass",
        "()Ljava/lang/Class;",
        native_return_null,
    );
    registry.register(
        c,
        "getNestHost",
        "()Ljava/lang/Class;",
        native_class_get_nest_host,
    );
    registry.register(
        c,
        "getEnumConstants",
        "()[Ljava/lang/Object;",
        native_class_get_enum_constants,
    );
    // Package-private `Class.getEnumConstantsShared()` — backs
    // `EnumMap.getKeyUniverse` via `SharedSecrets.getJavaLangAccess()`.
    // The real JDK implements it in Java using reflection (getMethod +
    // invoke on `values()`), but our reflection stack still returns null
    // for synthetic enum `values()` methods, so `EnumMap.<init>(Class)`
    // sees a null array and throws NPE on `arraylength`.  Override with
    // the same native so EnumMap / StreamOpFlag.<clinit> succeed.
    registry.register(
        c,
        "getEnumConstantsShared",
        "()[Ljava/lang/Object;",
        native_class_get_enum_constants,
    );
    registry.register(c, "desiredAssertionStatus", "()Z", native_return_false);
    registry.register(
        c,
        "cast",
        "(Ljava/lang/Object;)Ljava/lang/Object;",
        native_class_cast,
    );
    registry.register(
        c,
        "asSubclass",
        "(Ljava/lang/Class;)Ljava/lang/Class;",
        native_class_as_subclass,
    );
    registry.register(
        c,
        "getClassLoader",
        "()Ljava/lang/ClassLoader;",
        |ctx, args| {
            // JVM spec §5.3: bootstrap classes return null, others return the
            // defining loader. We read the ClassId from the mirror (field 0)
            // and look up which loader defined it. For mirrors that don't
            // carry a resolvable class id (synthetic test fixtures, or
            // application-user classes that haven't been registered with
            // the class manager yet), we default to the application
            // class loader — matching HotSpot behaviour for
            // dynamically-loaded user classes.
            let mirror = match args.first() {
                Some(Value::Object(Some(o))) => *o,
                _ => return Ok(Some(Value::Object(None))),
            };
            let class_id = match ctx.get_field(mirror, 0) {
                Value::Int(v) => rustjvm_types::ClassId::new(v as u32),
                _ => {
                    // Synthetic mirror with no stored ClassId — return the
                    // app loader so `Class.getClassLoader()` is never null
                    // for a non-bootstrap class. The only path that should
                    // yield null is the explicit Bootstrap case below.
                    let cl = crate::classloader::get_or_create_app_loader(ctx);
                    return Ok(Some(Value::Object(Some(cl))));
                }
            };
            let loader_type = ctx.loader_id_of_class(class_id);
            match loader_type {
                0 => {
                    // Bootstrap loader → null per JVM spec
                    Ok(Some(Value::Object(None)))
                }
                1 => {
                    // Platform/extension loader — return singleton
                    let cl = crate::classloader::get_or_create_platform_loader(ctx);
                    Ok(Some(Value::Object(Some(cl))))
                }
                _ => {
                    // Application or user-defined loader — return singleton
                    let cl = crate::classloader::get_or_create_app_loader(ctx);
                    Ok(Some(Value::Object(Some(cl))))
                }
            }
        },
    );
    registry.register(
        c,
        "toGenericString",
        "()Ljava/lang/String;",
        native_class_get_type_name,
    );
    registry.register(
        c,
        "descriptorString",
        "()Ljava/lang/String;",
        native_class_descriptor_string,
    );

    // --- Formatter (basic) ---
    register_formatter_natives(registry);

    // Note: StringWriter and StringReader already registered in io.rs

    // --- Collections extras: unmodifiable wrappers ---
    register_collections_extras_natives(registry);
    register_core_stdlib_extras(registry);
    register_scanner_natives(registry);

    // Note: CompletableFuture, Executors, Locale, Charset already registered in earlier phases
}

